insert into public.assessment_questions (kind, lesson_id, unit_id, course_id, prompt, choices, correct_choice_id, hint, order_index) values
  ('unit_exam', null, '6d2156e8-d4b0-4d1a-a9db-8728b30810a4', null, '{"en": "TCP/IP functions as:"}', '[{"id": "a", "text": {"en": "A single company''s proprietary software"}}, {"id": "b", "text": {"en": "A shared set of rules that lets different devices communicate"}}, {"id": "c", "text": {"en": "A type of malware"}}, {"id": "d", "text": {"en": "A physical cable standard"}}]', 'b', null, 1),
  ('unit_exam', null, '6d2156e8-d4b0-4d1a-a9db-8728b30810a4', null, '{"en": "Data sent over the internet is broken into small units called:"}', '[{"id": "a", "text": {"en": "Cookies"}}, {"id": "b", "text": {"en": "Tokens"}}, {"id": "c", "text": {"en": "Caches"}}, {"id": "d", "text": {"en": "Packets"}}]', 'd', null, 2),
  ('unit_exam', null, '6d2156e8-d4b0-4d1a-a9db-8728b30810a4', null, '{"en": "Port 443 is commonly used for:"}', '[{"id": "a", "text": {"en": "Secure web traffic (HTTPS)"}}, {"id": "b", "text": {"en": "Unencrypted web traffic"}}, {"id": "c", "text": {"en": "Email only"}}, {"id": "d", "text": {"en": "File printing"}}]', 'a', null, 3),
  ('unit_exam', null, '6d2156e8-d4b0-4d1a-a9db-8728b30810a4', null, '{"en": "Scanning for open ports is a technique attackers use to:"}', '[{"id": "a", "text": {"en": "Improve their internet speed"}}, {"id": "b", "text": {"en": "Update their antivirus"}}, {"id": "c", "text": {"en": "Find an unlocked entry point into a system"}}, {"id": "d", "text": {"en": "Generate stronger passwords"}}]', 'c', null, 4),
  ('unit_exam', null, '6d2156e8-d4b0-4d1a-a9db-8728b30810a4', null, '{"en": "DNS is best described as:"}', '[{"id": "a", "text": {"en": "A type of firewall"}}, {"id": "b", "text": {"en": "The internet''s phone book, translating names into IP addresses"}}, {"id": "c", "text": {"en": "An encryption algorithm"}}, {"id": "d", "text": {"en": "A password manager"}}]', 'b', null, 5),
  ('unit_exam', null, '6d2156e8-d4b0-4d1a-a9db-8728b30810a4', null, '{"en": "In a DNS spoofing attack, the attacker:"}', '[{"id": "a", "text": {"en": "Feeds false information to a DNS server to redirect victims to a fake site"}}, {"id": "b", "text": {"en": "Physically damages a router"}}, {"id": "c", "text": {"en": "Deletes a victim''s files"}}, {"id": "d", "text": {"en": "Strengthens DNS security"}}]', 'a', null, 6),
  ('unit_exam', null, '6d2156e8-d4b0-4d1a-a9db-8728b30810a4', null, '{"en": "DNS hijacking specifically involves:"}', '[{"id": "a", "text": {"en": "Creating a new domain name"}}, {"id": "b", "text": {"en": "Installing antivirus software"}}, {"id": "c", "text": {"en": "Blocking all internet access"}}, {"id": "d", "text": {"en": "Changing DNS settings on a device or router directly"}}]', 'd', null, 7),
  ('unit_exam', null, '6d2156e8-d4b0-4d1a-a9db-8728b30810a4', null, '{"en": "A reliable sign that a site might not be what it claims, even with a spoofed DNS entry, is:"}', '[{"id": "a", "text": {"en": "A slow loading time"}}, {"id": "b", "text": {"en": "A colorful design"}}, {"id": "c", "text": {"en": "A certificate warning, since spoofed sites often can''t fake a valid HTTPS certificate"}}, {"id": "d", "text": {"en": "A short domain name"}}]', 'c', null, 8),
  ('unit_exam', null, '6d2156e8-d4b0-4d1a-a9db-8728b30810a4', null, '{"en": "Network segmentation is the practice of:"}', '[{"id": "a", "text": {"en": "Merging all devices onto one shared network"}}, {"id": "b", "text": {"en": "Splitting a network into separate zones to limit how far a breach can spread"}}, {"id": "c", "text": {"en": "Disabling the internet entirely"}}, {"id": "d", "text": {"en": "Deleting old network logs"}}]', 'b', null, 9),
  ('unit_exam', null, '6d2156e8-d4b0-4d1a-a9db-8728b30810a4', null, '{"en": "A VLAN is used to:"}', '[{"id": "a", "text": {"en": "Increase Wi-Fi signal range"}}, {"id": "b", "text": {"en": "Speed up video streaming"}}, {"id": "c", "text": {"en": "Encrypt files automatically"}}, {"id": "d", "text": {"en": "Create isolated virtual zones within a network"}}]', 'd', null, 10),
  ('unit_exam', null, '6d2156e8-d4b0-4d1a-a9db-8728b30810a4', null, '{"en": "Isolating guest wifi from internal company systems is an example of:"}', '[{"id": "a", "text": {"en": "Network segmentation in action"}}, {"id": "b", "text": {"en": "Poor practice that should be avoided"}}, {"id": "c", "text": {"en": "A type of phishing"}}, {"id": "d", "text": {"en": "A firewall bypass"}}]', 'a', null, 11),
  ('unit_exam', null, '6d2156e8-d4b0-4d1a-a9db-8728b30810a4', null, '{"en": "In a \"flat,\" unsegmented network, a single compromised device can:"}', '[{"id": "a", "text": {"en": "Only affect itself"}}, {"id": "b", "text": {"en": "Automatically get isolated"}}, {"id": "c", "text": {"en": "Potentially reach and affect everything else on that network"}}, {"id": "d", "text": {"en": "Improve the network''s overall security"}}]', 'c', null, 12),
  ('unit_exam', null, '6d2156e8-d4b0-4d1a-a9db-8728b30810a4', null, '{"en": "Which combination reflects good network security practice from this unit?"}', '[{"id": "a", "text": {"en": "Segmented zones, a trusted DNS provider, and only necessary ports open"}}, {"id": "b", "text": {"en": "One flat network, all default DNS settings, all ports open"}}, {"id": "c", "text": {"en": "No segmentation and unrestricted DNS"}}, {"id": "d", "text": {"en": "Disabling all firewalls for convenience"}}]', 'a', null, 13),
  ('unit_exam', null, '8faa1f95-f823-4bc6-bc0f-8e8257702e5d', null, '{"en": "In the shared responsibility model, the cloud provider is generally responsible for:"}', '[{"id": "a", "text": {"en": "The physical infrastructure and underlying hardware"}}, {"id": "b", "text": {"en": "Your specific data and configurations"}}, {"id": "c", "text": {"en": "Nothing at all"}}, {"id": "d", "text": {"en": "Your personal passwords"}}]', 'a', null, 1),
  ('unit_exam', null, '8faa1f95-f823-4bc6-bc0f-8e8257702e5d', null, '{"en": "In the shared responsibility model, the customer is generally responsible for:"}', '[{"id": "a", "text": {"en": "The physical data center security"}}, {"id": "b", "text": {"en": "The core network infrastructure"}}, {"id": "c", "text": {"en": "Their own data, access controls, and configurations"}}, {"id": "d", "text": {"en": "Nothing; it''s all automatic"}}]', 'c', null, 2),
  ('unit_exam', null, '8faa1f95-f823-4bc6-bc0f-8e8257702e5d', null, '{"en": "The apartment analogy in this unit compares the cloud provider to:"}', '[{"id": "a", "text": {"en": "A tenant"}}, {"id": "b", "text": {"en": "A landlord securing the building itself"}}, {"id": "c", "text": {"en": "A burglar"}}, {"id": "d", "text": {"en": "A neighbor"}}]', 'b', null, 3),
  ('unit_exam', null, '8faa1f95-f823-4bc6-bc0f-8e8257702e5d', null, '{"en": "What does IAM stand for?"}', '[{"id": "a", "text": {"en": "Internet Access Monitoring"}}, {"id": "b", "text": {"en": "Internal Antivirus Module"}}, {"id": "c", "text": {"en": "Integrated Access Model"}}, {"id": "d", "text": {"en": "Identity and Access Management"}}]', 'd', null, 4),
  ('unit_exam', null, '8faa1f95-f823-4bc6-bc0f-8e8257702e5d', null, '{"en": "The principle of least privilege means:"}', '[{"id": "a", "text": {"en": "Giving users only the access they actually need to do their job"}}, {"id": "b", "text": {"en": "Giving every user full administrative access"}}, {"id": "c", "text": {"en": "Removing access from everyone equally"}}, {"id": "d", "text": {"en": "Sharing one login across a whole team"}}]', 'a', null, 5),
  ('unit_exam', null, '8faa1f95-f823-4bc6-bc0f-8e8257702e5d', null, '{"en": "Many real-world cloud breaches happen mainly because:"}', '[{"id": "a", "text": {"en": "Attackers use extremely rare, advanced exploits"}}, {"id": "b", "text": {"en": "Cloud providers refuse to offer any security"}}, {"id": "c", "text": {"en": "Segmentation was overused"}}, {"id": "d", "text": {"en": "Accounts had far more access than they actually needed"}}]', 'd', null, 6),
  ('unit_exam', null, '8faa1f95-f823-4bc6-bc0f-8e8257702e5d', null, '{"en": "When an employee leaves a company, their cloud access should be:"}', '[{"id": "a", "text": {"en": "Left active just in case"}}, {"id": "b", "text": {"en": "Passed on to a new hire without changes"}}, {"id": "c", "text": {"en": "Revoked immediately"}}, {"id": "d", "text": {"en": "Ignored until the next audit"}}]', 'c', null, 7),
  ('unit_exam', null, '8faa1f95-f823-4bc6-bc0f-8e8257702e5d', null, '{"en": "What causes the majority of cloud security incidents, according to this unit?"}', '[{"id": "a", "text": {"en": "Sophisticated technical exploits exclusively"}}, {"id": "b", "text": {"en": "Simple misconfigurations, like storage left publicly accessible"}}, {"id": "c", "text": {"en": "Hardware failures"}}, {"id": "d", "text": {"en": "Weather-related outages"}}]', 'b', null, 8),
  ('unit_exam', null, '8faa1f95-f823-4bc6-bc0f-8e8257702e5d', null, '{"en": "A cloud storage bucket accidentally left \"public\" instead of \"private\" is an example of:"}', '[{"id": "a", "text": {"en": "A misconfiguration"}}, {"id": "b", "text": {"en": "Strong access control"}}, {"id": "c", "text": {"en": "A firewall rule"}}, {"id": "d", "text": {"en": "A form of encryption"}}]', 'a', null, 9),
  ('unit_exam', null, '8faa1f95-f823-4bc6-bc0f-8e8257702e5d', null, '{"en": "What should be the default assumption for cloud storage access settings?"}', '[{"id": "a", "text": {"en": "Public by default"}}, {"id": "b", "text": {"en": "Shared with every user automatically"}}, {"id": "c", "text": {"en": "Private by default, public only for a clear, deliberate reason"}}, {"id": "d", "text": {"en": "It doesn''t matter"}}]', 'c', null, 10),
  ('unit_exam', null, '8faa1f95-f823-4bc6-bc0f-8e8257702e5d', null, '{"en": "Why are automated configuration-scanning tools valuable for cloud security?"}', '[{"id": "a", "text": {"en": "They eliminate the need for any human oversight"}}, {"id": "b", "text": {"en": "They make all data public for easier access"}}, {"id": "c", "text": {"en": "They only work for very small companies"}}, {"id": "d", "text": {"en": "Manual review doesn''t scale, so automation helps catch exposed settings"}}]', 'd', null, 11),
  ('unit_exam', null, '8faa1f95-f823-4bc6-bc0f-8e8257702e5d', null, '{"en": "\"The cloud is secure\" and \"my setup inside the cloud is secure\" are:"}', '[{"id": "a", "text": {"en": "Always exactly the same thing"}}, {"id": "b", "text": {"en": "Not the same thing - the provider''s security doesn''t cover your own configuration mistakes"}}, {"id": "c", "text": {"en": "Completely unrelated concepts"}}, {"id": "d", "text": {"en": "Only relevant to large enterprises"}}]', 'b', null, 12),
  ('unit_exam', null, '8faa1f95-f823-4bc6-bc0f-8e8257702e5d', null, '{"en": "Which combination reflects strong cloud security practice from this unit?"}', '[{"id": "a", "text": {"en": "Private-by-default storage, least-privilege access, and regular configuration audits"}}, {"id": "b", "text": {"en": "Default public storage, shared admin accounts, and no access reviews"}}, {"id": "c", "text": {"en": "Ignoring the shared responsibility model entirely"}}, {"id": "d", "text": {"en": "Never revoking access for departed employees"}}]', 'a', null, 13),
  ('unit_exam', null, 'ef1d29e3-a4e6-4d02-b104-3d9d81c9a304', null, '{"en": "The OWASP Top 10 is best described as:"}', '[{"id": "a", "text": {"en": "The industry''s go-to list of the most critical web application security risks"}}, {"id": "b", "text": {"en": "A list of the fastest websites"}}, {"id": "c", "text": {"en": "A programming language"}}, {"id": "d", "text": {"en": "A type of firewall"}}]', 'a', null, 1),
  ('unit_exam', null, 'ef1d29e3-a4e6-4d02-b104-3d9d81c9a304', null, '{"en": "Broken authentication can occur when a login system has:"}', '[{"id": "a", "text": {"en": "Strong password requirements"}}, {"id": "b", "text": {"en": "Multi-factor authentication enabled"}}, {"id": "c", "text": {"en": "Weak points like no lockout after failed attempts or predictable session tokens"}}, {"id": "d", "text": {"en": "Regular security audits"}}]', 'c', null, 2),
  ('unit_exam', null, 'ef1d29e3-a4e6-4d02-b104-3d9d81c9a304', null, '{"en": "Insecure deserialization becomes dangerous when an application:"}', '[{"id": "a", "text": {"en": "Rejects all incoming data automatically"}}, {"id": "b", "text": {"en": "Blindly trusts incoming data without checking it before converting it back to use"}}, {"id": "c", "text": {"en": "Never stores any data"}}, {"id": "d", "text": {"en": "Uses only encrypted connections"}}]', 'b', null, 3),
  ('unit_exam', null, 'ef1d29e3-a4e6-4d02-b104-3d9d81c9a304', null, '{"en": "Security misconfiguration typically involves:"}', '[{"id": "a", "text": {"en": "A highly advanced, rare technical exploit"}}, {"id": "b", "text": {"en": "Perfectly configured default settings"}}, {"id": "c", "text": {"en": "Something limited only to mobile devices"}}, {"id": "d", "text": {"en": "Simple unchecked details like default accounts left active or overly revealing error messages"}}]', 'd', null, 4),
  ('unit_exam', null, 'ef1d29e3-a4e6-4d02-b104-3d9d81c9a304', null, '{"en": "CSRF tricks a victim''s browser into:"}', '[{"id": "a", "text": {"en": "Sending an unintended request to a site they''re already logged into"}}, {"id": "b", "text": {"en": "Permanently deleting their account"}}, {"id": "c", "text": {"en": "Encrypting their session token"}}, {"id": "d", "text": {"en": "Blocking their internet access"}}]', 'a', null, 5),
  ('unit_exam', null, 'ef1d29e3-a4e6-4d02-b104-3d9d81c9a304', null, '{"en": "A session token''s role is to:"}', '[{"id": "a", "text": {"en": "Store your password in plaintext"}}, {"id": "b", "text": {"en": "Slow down your browsing"}}, {"id": "c", "text": {"en": "Replace the need for HTTPS"}}, {"id": "d", "text": {"en": "Prove you''re authenticated, and get attached automatically to your requests to that site"}}]', 'd', null, 6),
  ('unit_exam', null, 'ef1d29e3-a4e6-4d02-b104-3d9d81c9a304', null, '{"en": "SameSite cookies help prevent CSRF by:"}', '[{"id": "a", "text": {"en": "Encrypting all website traffic"}}, {"id": "b", "text": {"en": "Deleting all cookies immediately"}}, {"id": "c", "text": {"en": "Stopping cookies from being sent with requests that originate from a different site"}}, {"id": "d", "text": {"en": "Making every cookie public"}}]', 'c', null, 7),
  ('unit_exam', null, 'ef1d29e3-a4e6-4d02-b104-3d9d81c9a304', null, '{"en": "A practical personal habit that reduces CSRF risk is:"}', '[{"id": "a", "text": {"en": "Staying logged into your bank in every browser tab at all times"}}, {"id": "b", "text": {"en": "Logging out of sensitive accounts when you''re done, rather than just closing the tab"}}, {"id": "c", "text": {"en": "Never using cookies at all"}}, {"id": "d", "text": {"en": "Disabling your browser''s security settings"}}]', 'b', null, 8),
  ('unit_exam', null, 'ef1d29e3-a4e6-4d02-b104-3d9d81c9a304', null, '{"en": "The Secure Development Lifecycle (SDLC) treats security as:"}', '[{"id": "a", "text": {"en": "A thread running through every stage of development, not just a final step"}}, {"id": "b", "text": {"en": "Something only relevant after a breach occurs"}}, {"id": "c", "text": {"en": "A task exclusively for the testing team"}}, {"id": "d", "text": {"en": "An optional add-on for large companies only"}}]', 'a', null, 9),
  ('unit_exam', null, 'ef1d29e3-a4e6-4d02-b104-3d9d81c9a304', null, '{"en": "During the \"design\" stage of the SDLC, developers should be asking:"}', '[{"id": "a", "text": {"en": "How fast can this ship?"}}, {"id": "b", "text": {"en": "What color scheme fits best?"}}, {"id": "c", "text": {"en": "How could this feature be abused?"}}, {"id": "d", "text": {"en": "How many users will this attract?"}}]', 'c', null, 10),
  ('unit_exam', null, 'ef1d29e3-a4e6-4d02-b104-3d9d81c9a304', null, '{"en": "Secure coding standards typically include:"}', '[{"id": "a", "text": {"en": "Hardcoding passwords directly into source code"}}, {"id": "b", "text": {"en": "Trusting all user input by default"}}, {"id": "c", "text": {"en": "Skipping validation to save development time"}}, {"id": "d", "text": {"en": "Validating input and never trusting data from the user"}}]', 'd', null, 11),
  ('unit_exam', null, 'ef1d29e3-a4e6-4d02-b104-3d9d81c9a304', null, '{"en": "Code review is valuable mainly because:"}', '[{"id": "a", "text": {"en": "It''s required by law in every country"}}, {"id": "b", "text": {"en": "A second set of eyes catches what the original developer missed"}}, {"id": "c", "text": {"en": "It eliminates the need for any testing"}}, {"id": "d", "text": {"en": "It only matters for very small projects"}}]', 'b', null, 12),
  ('unit_exam', null, 'ef1d29e3-a4e6-4d02-b104-3d9d81c9a304', null, '{"en": "Why is it generally cheaper to build security in from the start rather than fixing it after launch?"}', '[{"id": "a", "text": {"en": "Fixing a security flaw after release costs dramatically more than catching it during design"}}, {"id": "b", "text": {"en": "Security fixes are always free regardless of timing"}}, {"id": "c", "text": {"en": "Early security work always costs more"}}, {"id": "d", "text": {"en": "There''s no cost difference either way"}}]', 'a', null, 13),
  ('unit_exam', null, 'c4be79c7-4470-49b3-9b14-43aca2dd5fad', null, '{"en": "WEP, as a wifi security standard, is now considered:"}', '[{"id": "a", "text": {"en": "The most secure option available"}}, {"id": "b", "text": {"en": "Equivalent to WPA3"}}, {"id": "c", "text": {"en": "Impossible to crack"}}, {"id": "d", "text": {"en": "Badly broken and crackable by freely available tools"}}]', 'd', null, 1),
  ('unit_exam', null, 'c4be79c7-4470-49b3-9b14-43aca2dd5fad', null, '{"en": "WPA3 improves on earlier standards mainly by:"}', '[{"id": "a", "text": {"en": "Removing all encryption for speed"}}, {"id": "b", "text": {"en": "Adding stronger protection even when a user has a weak password"}}, {"id": "c", "text": {"en": "Only working with wired connections"}}, {"id": "d", "text": {"en": "Disabling wifi entirely"}}]', 'b', null, 2),
  ('unit_exam', null, 'c4be79c7-4470-49b3-9b14-43aca2dd5fad', null, '{"en": "KRACK is a known vulnerability that affects:"}', '[{"id": "a", "text": {"en": "WPA2"}}, {"id": "b", "text": {"en": "Only Bluetooth devices"}}, {"id": "c", "text": {"en": "Wired ethernet only"}}, {"id": "d", "text": {"en": "Physical router hardware exclusively"}}]', 'a', null, 3),
  ('unit_exam', null, 'c4be79c7-4470-49b3-9b14-43aca2dd5fad', null, '{"en": "A practical wifi security takeaway from this unit is to:"}', '[{"id": "a", "text": {"en": "Assume all wifi standards are equally safe"}}, {"id": "b", "text": {"en": "Never update router settings"}}, {"id": "c", "text": {"en": "Check your router and upgrade away from WEP or plain WPA if found"}}, {"id": "d", "text": {"en": "Avoid using wifi entirely"}}]', 'c', null, 4),
  ('unit_exam', null, 'c4be79c7-4470-49b3-9b14-43aca2dd5fad', null, '{"en": "Bluejacking involves:"}', '[{"id": "a", "text": {"en": "Stealing a device''s stored files"}}, {"id": "b", "text": {"en": "Physically damaging Bluetooth hardware"}}, {"id": "c", "text": {"en": "Encrypting a victim''s data"}}, {"id": "d", "text": {"en": "Sending unsolicited messages to nearby discoverable Bluetooth devices"}}]', 'd', null, 5),
  ('unit_exam', null, 'c4be79c7-4470-49b3-9b14-43aca2dd5fad', null, '{"en": "Bluesnarfing is considered dangerous because it can:"}', '[{"id": "a", "text": {"en": "Let an attacker access data like contacts and files without permission"}}, {"id": "b", "text": {"en": "Only send harmless messages"}}, {"id": "c", "text": {"en": "Require the victim''s explicit consent first"}}, {"id": "d", "text": {"en": "Only affect devices with Bluetooth turned off"}}]', 'a', null, 6),
  ('unit_exam', null, 'c4be79c7-4470-49b3-9b14-43aca2dd5fad', null, '{"en": "BlueBorne, discovered in 2017, was significant because it could:"}', '[{"id": "a", "text": {"en": "Only affect desktop computers with no Bluetooth"}}, {"id": "b", "text": {"en": "Let an attacker take over a device without any pairing or click at all"}}, {"id": "c", "text": {"en": "Only work over wifi, not Bluetooth"}}, {"id": "d", "text": {"en": "Be fixed without ever needing a software update"}}]', 'b', null, 7),
  ('unit_exam', null, 'c4be79c7-4470-49b3-9b14-43aca2dd5fad', null, '{"en": "A practical way to reduce Bluetooth-related risk is to:"}', '[{"id": "a", "text": {"en": "Always keep Bluetooth discoverable"}}, {"id": "b", "text": {"en": "Accept every pairing request automatically"}}, {"id": "c", "text": {"en": "Turn Bluetooth off when not actively using it"}}, {"id": "d", "text": {"en": "Avoid ever updating your device"}}]', 'c', null, 8),
  ('unit_exam', null, 'c4be79c7-4470-49b3-9b14-43aca2dd5fad', null, '{"en": "A flashlight app requesting access to your contacts and location is:"}', '[{"id": "a", "text": {"en": "A completely normal technical requirement"}}, {"id": "b", "text": {"en": "Required by every app store"}}, {"id": "c", "text": {"en": "A sign the app is well-designed"}}, {"id": "d", "text": {"en": "A red flag, since it has no real technical need for that access"}}]', 'd', null, 9),
  ('unit_exam', null, 'c4be79c7-4470-49b3-9b14-43aca2dd5fad', null, '{"en": "Every permission granted to a mobile app represents:"}', '[{"id": "a", "text": {"en": "A potential channel for abuse if misused"}}, {"id": "b", "text": {"en": "A guaranteed security improvement"}}, {"id": "c", "text": {"en": "Something that''s automatically reviewed weekly"}}, {"id": "d", "text": {"en": "A requirement that can never be revoked"}}]', 'a', null, 10),
  ('unit_exam', null, 'c4be79c7-4470-49b3-9b14-43aca2dd5fad', null, '{"en": "Mobile malware is often distributed by:"}', '[{"id": "a", "text": {"en": "Exclusively through official, top-rated app store listings"}}, {"id": "b", "text": {"en": "Government security agencies"}}, {"id": "c", "text": {"en": "Disguising itself as a legitimate app, sometimes outside official app stores"}}, {"id": "d", "text": {"en": "Physical mail only"}}]', 'c', null, 11),
  ('unit_exam', null, 'c4be79c7-4470-49b3-9b14-43aca2dd5fad', null, '{"en": "A good practical habit for managing app permissions is to:"}', '[{"id": "a", "text": {"en": "Grant every requested permission without question"}}, {"id": "b", "text": {"en": "Regularly review and revoke permissions no longer needed"}}, {"id": "c", "text": {"en": "Never install any mobile apps"}}, {"id": "d", "text": {"en": "Ignore all app store reviews"}}]', 'b', null, 12),
  ('unit_exam', null, 'c4be79c7-4470-49b3-9b14-43aca2dd5fad', null, '{"en": "The overall lesson from this unit about wireless and mobile security is that:"}', '[{"id": "a", "text": {"en": "Wireless connections are inherently completely safe"}}, {"id": "b", "text": {"en": "Only large companies need to worry about these risks"}}, {"id": "c", "text": {"en": "Bluetooth and wifi risks are purely theoretical"}}, {"id": "d", "text": {"en": "Small, often-overlooked settings - like wifi standards, Bluetooth visibility, and app permissions - meaningfully affect your real-world security"}}]', 'd', null, 13),
  ('unit_exam', null, 'c1d7b9a9-5431-4afd-a883-72f8a66c352f', null, '{"en": "A digital certificate is issued by:"}', '[{"id": "a", "text": {"en": "A trusted third party called a Certificate Authority"}}, {"id": "b", "text": {"en": "The website owner alone"}}, {"id": "c", "text": {"en": "Your internet service provider"}}, {"id": "d", "text": {"en": "Your antivirus software"}}]', 'a', null, 1),
  ('unit_exam', null, 'c1d7b9a9-5431-4afd-a883-72f8a66c352f', null, '{"en": "A digital signature proves:"}', '[{"id": "a", "text": {"en": "Only that a file is small"}}, {"id": "b", "text": {"en": "Nothing useful"}}, {"id": "c", "text": {"en": "That content came from the claimed source and hasn''t been tampered with"}}, {"id": "d", "text": {"en": "That a website loads quickly"}}]', 'c', null, 2),
  ('unit_exam', null, 'c1d7b9a9-5431-4afd-a883-72f8a66c352f', null, '{"en": "A digital signature is created using:"}', '[{"id": "a", "text": {"en": "A shared password"}}, {"id": "b", "text": {"en": "The signer''s private key"}}, {"id": "c", "text": {"en": "The signer''s public key"}}, {"id": "d", "text": {"en": "A firewall rule"}}]', 'b', null, 3),
  ('unit_exam', null, 'c1d7b9a9-5431-4afd-a883-72f8a66c352f', null, '{"en": "The padlock icon in your browser mainly confirms:"}', '[{"id": "a", "text": {"en": "The site''s content is completely trustworthy"}}, {"id": "b", "text": {"en": "The site loads faster than others"}}, {"id": "c", "text": {"en": "The site has no ads"}}, {"id": "d", "text": {"en": "You''re actually communicating with the domain you think you are"}}]', 'd', null, 4),
  ('unit_exam', null, 'c1d7b9a9-5431-4afd-a883-72f8a66c352f', null, '{"en": "PKI is:"}', '[{"id": "a", "text": {"en": "The entire framework of trust that makes certificate-based verification work"}}, {"id": "b", "text": {"en": "A single company"}}, {"id": "c", "text": {"en": "A type of firewall"}}, {"id": "d", "text": {"en": "A password manager"}}]', 'a', null, 5),
  ('unit_exam', null, 'c1d7b9a9-5431-4afd-a883-72f8a66c352f', null, '{"en": "The \"chain of trust\" ultimately traces back to:"}', '[{"id": "a", "text": {"en": "Your internet service provider"}}, {"id": "b", "text": {"en": "The website itself"}}, {"id": "c", "text": {"en": "A random server"}}, {"id": "d", "text": {"en": "A trusted root Certificate Authority built into your browser"}}]', 'd', null, 6),
  ('unit_exam', null, 'c1d7b9a9-5431-4afd-a883-72f8a66c352f', null, '{"en": "Root CAs can vouch for:"}', '[{"id": "a", "text": {"en": "Nothing else"}}, {"id": "b", "text": {"en": "Only themselves"}}, {"id": "c", "text": {"en": "Intermediate CAs, which then issue certificates to websites"}}, {"id": "d", "text": {"en": "Your personal devices"}}]', 'c', null, 7),
  ('unit_exam', null, 'c1d7b9a9-5431-4afd-a883-72f8a66c352f', null, '{"en": "When a certificate is improperly issued or a CA is compromised, browsers can:"}', '[{"id": "a", "text": {"en": "Ignore the problem entirely"}}, {"id": "b", "text": {"en": "Revoke trust in specific certificates"}}, {"id": "c", "text": {"en": "Automatically fix the certificate"}}, {"id": "d", "text": {"en": "Shut down the internet"}}]', 'b', null, 8),
  ('unit_exam', null, 'c1d7b9a9-5431-4afd-a883-72f8a66c352f', null, '{"en": "The TLS handshake happens:"}', '[{"id": "a", "text": {"en": "Automatically, every time you connect to an HTTPS site"}}, {"id": "b", "text": {"en": "Only once per year"}}, {"id": "c", "text": {"en": "Manually, initiated by the user"}}, {"id": "d", "text": {"en": "Only when there''s an error"}}]', 'a', null, 9),
  ('unit_exam', null, 'c1d7b9a9-5431-4afd-a883-72f8a66c352f', null, '{"en": "During the handshake, the server proves its identity by presenting:"}', '[{"id": "a", "text": {"en": "A password"}}, {"id": "b", "text": {"en": "Its IP address only"}}, {"id": "c", "text": {"en": "Its digital certificate"}}, {"id": "d", "text": {"en": "A firewall rule"}}]', 'c', null, 10),
  ('unit_exam', null, 'c1d7b9a9-5431-4afd-a883-72f8a66c352f', null, '{"en": "The session key established during the handshake is used for:"}', '[{"id": "a", "text": {"en": "Storing your password"}}, {"id": "b", "text": {"en": "Displaying the website''s logo"}}, {"id": "c", "text": {"en": "Nothing important"}}, {"id": "d", "text": {"en": "Symmetric encryption of the actual conversation going forward"}}]', 'd', null, 11),
  ('unit_exam', null, 'c1d7b9a9-5431-4afd-a883-72f8a66c352f', null, '{"en": "Why is symmetric encryption used for the bulk of the actual data after the handshake?"}', '[{"id": "a", "text": {"en": "Asymmetric encryption doesn''t exist"}}, {"id": "b", "text": {"en": "It''s faster and more efficient than asymmetric encryption"}}, {"id": "c", "text": {"en": "It''s less secure but looks better"}}, {"id": "d", "text": {"en": "It''s illegal for large data"}}]', 'b', null, 12),
  ('unit_exam', null, 'c1d7b9a9-5431-4afd-a883-72f8a66c352f', null, '{"en": "Overall, TLS combines:"}', '[{"id": "a", "text": {"en": "Asymmetric encryption to agree on a key, then symmetric encryption for the actual data"}}, {"id": "b", "text": {"en": "Only symmetric encryption throughout"}}, {"id": "c", "text": {"en": "Only asymmetric encryption throughout"}}, {"id": "d", "text": {"en": "No encryption at all"}}]', 'a', null, 13),
  ('unit_exam', null, '8f673e9a-abf4-4b26-b87c-ca60908fa138', null, '{"en": "Passive reconnaissance involves:"}', '[{"id": "a", "text": {"en": "Directly hacking into a system"}}, {"id": "b", "text": {"en": "Sending malware to the target"}}, {"id": "c", "text": {"en": "Only reading company financial reports"}}, {"id": "d", "text": {"en": "Gathering information without directly interacting with the target''s systems"}}]', 'd', null, 1),
  ('unit_exam', null, '8f673e9a-abf4-4b26-b87c-ca60908fa138', null, '{"en": "Active reconnaissance, unlike passive, involves:"}', '[{"id": "a", "text": {"en": "No interaction with anything at all"}}, {"id": "b", "text": {"en": "Directly interacting with the target''s systems"}}, {"id": "c", "text": {"en": "Only reading public news articles"}}, {"id": "d", "text": {"en": "Skipping straight to exploitation"}}]', 'b', null, 2),
  ('unit_exam', null, '8f673e9a-abf4-4b26-b87c-ca60908fa138', null, '{"en": "Scanning, following reconnaissance, is used to:"}', '[{"id": "a", "text": {"en": "Systematically probe discovered systems for known vulnerabilities and weak points"}}, {"id": "b", "text": {"en": "Delete data"}}, {"id": "c", "text": {"en": "Send phishing emails"}}, {"id": "d", "text": {"en": "Encrypt files"}}]', 'a', null, 3),
  ('unit_exam', null, '8f673e9a-abf4-4b26-b87c-ca60908fa138', null, '{"en": "Why do skilled testers spend significant time on reconnaissance?"}', '[{"id": "a", "text": {"en": "It''s required by law"}}, {"id": "b", "text": {"en": "It has no real benefit"}}, {"id": "c", "text": {"en": "Attacking blind wastes time and increases the risk of getting caught before finding anything useful"}}, {"id": "d", "text": {"en": "It''s the fastest part of the process"}}]', 'c', null, 4),
  ('unit_exam', null, '8f673e9a-abf4-4b26-b87c-ca60908fa138', null, '{"en": "An exploit is:"}', '[{"id": "a", "text": {"en": "A type of firewall"}}, {"id": "b", "text": {"en": "A password policy"}}, {"id": "c", "text": {"en": "A backup strategy"}}, {"id": "d", "text": {"en": "A piece of code or technique that takes advantage of a specific vulnerability"}}]', 'd', null, 5),
  ('unit_exam', null, '8f673e9a-abf4-4b26-b87c-ca60908fa138', null, '{"en": "Privilege escalation means:"}', '[{"id": "a", "text": {"en": "Turning limited access into broader access"}}, {"id": "b", "text": {"en": "Deleting all user accounts"}}, {"id": "c", "text": {"en": "Reducing everyone''s access to nothing"}}, {"id": "d", "text": {"en": "Installing new software"}}]', 'a', null, 6),
  ('unit_exam', null, '8f673e9a-abf4-4b26-b87c-ca60908fa138', null, '{"en": "Post-exploitation focuses on:"}', '[{"id": "a", "text": {"en": "Immediately ending the entire test"}}, {"id": "b", "text": {"en": "Understanding what an attacker could actually do with the access gained"}}, {"id": "c", "text": {"en": "Ignoring the access once it''s gained"}}, {"id": "d", "text": {"en": "Only checking the time of day"}}]', 'b', null, 7),
  ('unit_exam', null, '8f673e9a-abf4-4b26-b87c-ca60908fa138', null, '{"en": "Why do penetration testers actually exploit vulnerabilities rather than just reporting them theoretically?"}', '[{"id": "a", "text": {"en": "It''s required for fun"}}, {"id": "b", "text": {"en": "Theoretical vulnerabilities are always ignored completely regardless"}}, {"id": "c", "text": {"en": "Demonstrating a vulnerability is real and exploitable often drives organizations to actually fix it"}}, {"id": "d", "text": {"en": "There''s no real reason"}}]', 'c', null, 8),
  ('unit_exam', null, '8f673e9a-abf4-4b26-b87c-ca60908fa138', null, '{"en": "The most valuable deliverable of a penetration test is often:"}', '[{"id": "a", "text": {"en": "The exploit code itself"}}, {"id": "b", "text": {"en": "A list of every employee''s name"}}, {"id": "c", "text": {"en": "A new firewall"}}, {"id": "d", "text": {"en": "The report"}}]', 'd', null, 9),
  ('unit_exam', null, '8f673e9a-abf4-4b26-b87c-ca60908fa138', null, '{"en": "An executive summary in a pentest report is meant for:"}', '[{"id": "a", "text": {"en": "Leadership, focused on business risk rather than technical detail"}}, {"id": "b", "text": {"en": "Only technical staff"}}, {"id": "c", "text": {"en": "Marketing purposes only"}}, {"id": "d", "text": {"en": "No one; it''s optional filler"}}]', 'a', null, 10),
  ('unit_exam', null, '8f673e9a-abf4-4b26-b87c-ca60908fa138', null, '{"en": "Risk ratings in a report help by:"}', '[{"id": "a", "text": {"en": "Making every issue seem equally urgent"}}, {"id": "b", "text": {"en": "Hiding the most dangerous findings"}}, {"id": "c", "text": {"en": "Prioritizing issues by actual severity and likelihood"}}, {"id": "d", "text": {"en": "Removing the need for remediation steps"}}]', 'c', null, 11),
  ('unit_exam', null, '8f673e9a-abf4-4b26-b87c-ca60908fa138', null, '{"en": "Remediation verification exists to:"}', '[{"id": "a", "text": {"en": "Skip confirming whether a fix actually worked"}}, {"id": "b", "text": {"en": "Confirm a vulnerability is actually resolved, not just reported as fixed"}}, {"id": "c", "text": {"en": "Replace the need for an initial report"}}, {"id": "d", "text": {"en": "Create unnecessary extra work"}}]', 'b', null, 12),
  ('unit_exam', null, '8f673e9a-abf4-4b26-b87c-ca60908fa138', null, '{"en": "Penetration testing is fundamentally about:"}', '[{"id": "a", "text": {"en": "Proving systems can always be broken, as an end in itself"}}, {"id": "b", "text": {"en": "Nothing practical"}}, {"id": "c", "text": {"en": "Only theoretical exercises"}}, {"id": "d", "text": {"en": "Finding realistic weaknesses before someone with worse intentions does, and giving a clear path to closing them"}}]', 'd', null, 13),
  ('unit_exam', null, 'c02cf568-c225-4c83-8c1e-f164b04a57a5', null, '{"en": "Digital forensics is best described as:"}', '[{"id": "a", "text": {"en": "Randomly guessing what happened"}}, {"id": "b", "text": {"en": "Deleting compromised systems immediately"}}, {"id": "c", "text": {"en": "Properly collecting, preserving, and analyzing digital evidence after an incident"}}, {"id": "d", "text": {"en": "A casual review with no documentation"}}]', 'c', null, 1),
  ('unit_exam', null, 'c02cf568-c225-4c83-8c1e-f164b04a57a5', null, '{"en": "Why shouldn''t you immediately power off a compromised machine?"}', '[{"id": "a", "text": {"en": "Doing so can wipe volatile data in memory that might hold crucial evidence"}}, {"id": "b", "text": {"en": "It''s against the law everywhere"}}, {"id": "c", "text": {"en": "It makes the investigation faster"}}, {"id": "d", "text": {"en": "It has no real downside"}}]', 'a', null, 2),
  ('unit_exam', null, 'c02cf568-c225-4c83-8c1e-f164b04a57a5', null, '{"en": "A forensic image is:"}', '[{"id": "a", "text": {"en": "A photograph of the server room"}}, {"id": "b", "text": {"en": "A marketing screenshot"}}, {"id": "c", "text": {"en": "A summary report only"}}, {"id": "d", "text": {"en": "An exact, bit-for-bit copy of the affected system"}}]', 'd', null, 3),
  ('unit_exam', null, 'c02cf568-c225-4c83-8c1e-f164b04a57a5', null, '{"en": "Why does rigorous documentation matter during first response?"}', '[{"id": "a", "text": {"en": "It''s optional and rarely useful"}}, {"id": "b", "text": {"en": "Sloppy response can destroy the very evidence needed to understand what happened"}}, {"id": "c", "text": {"en": "It slows down recovery unnecessarily"}}, {"id": "d", "text": {"en": "It''s only relevant for large companies"}}]', 'b', null, 4),
  ('unit_exam', null, 'c02cf568-c225-4c83-8c1e-f164b04a57a5', null, '{"en": "Chain of custody is:"}', '[{"id": "a", "text": {"en": "A type of firewall"}}, {"id": "b", "text": {"en": "A backup strategy"}}, {"id": "c", "text": {"en": "A documented, unbroken record of who handled evidence, when, and what they did with it"}}, {"id": "d", "text": {"en": "An encryption method"}}]', 'c', null, 5),
  ('unit_exam', null, 'c02cf568-c225-4c83-8c1e-f164b04a57a5', null, '{"en": "Why does chain of custody matter so much?"}', '[{"id": "a", "text": {"en": "It''s just a formality with no real purpose"}}, {"id": "b", "text": {"en": "It makes investigations slower for no reason"}}, {"id": "c", "text": {"en": "It''s only relevant for physical evidence"}}, {"id": "d", "text": {"en": "Without it, evidence could be argued as tampered with, altered, or mishandled"}}]', 'd', null, 6),
  ('unit_exam', null, 'c02cf568-c225-4c83-8c1e-f164b04a57a5', null, '{"en": "Which of these can break a chain of custody?"}', '[{"id": "a", "text": {"en": "Gaps in documentation when evidence changes hands"}}, {"id": "b", "text": {"en": "Using a verified copy for analysis"}}, {"id": "c", "text": {"en": "Properly securing storage"}}, {"id": "d", "text": {"en": "Logging every handoff"}}]', 'a', null, 7),
  ('unit_exam', null, 'c02cf568-c225-4c83-8c1e-f164b04a57a5', null, '{"en": "A practical mindset for handling digital evidence is to:"}', '[{"id": "a", "text": {"en": "Assume no one will ever question it"}}, {"id": "b", "text": {"en": "Treat every piece of evidence as if its authenticity will eventually be challenged"}}, {"id": "c", "text": {"en": "Skip documentation to save time"}}, {"id": "d", "text": {"en": "Only document evidence that seems important"}}]', 'b', null, 8),
  ('unit_exam', null, 'c02cf568-c225-4c83-8c1e-f164b04a57a5', null, '{"en": "Logs are:"}', '[{"id": "a", "text": {"en": "A type of encryption"}}, {"id": "b", "text": {"en": "Physical evidence only"}}, {"id": "c", "text": {"en": "Records that applications and systems automatically keep of events"}}, {"id": "d", "text": {"en": "Something that''s always immediately deleted"}}]', 'c', null, 9),
  ('unit_exam', null, 'c02cf568-c225-4c83-8c1e-f164b04a57a5', null, '{"en": "Metadata is best described as:"}', '[{"id": "a", "text": {"en": "Data about data, like a file''s creation date or location"}}, {"id": "b", "text": {"en": "The actual content of a file"}}, {"id": "c", "text": {"en": "A type of malware"}}, {"id": "d", "text": {"en": "A firewall setting"}}]', 'a', null, 10),
  ('unit_exam', null, 'c02cf568-c225-4c83-8c1e-f164b04a57a5', null, '{"en": "Artifacts, in a forensic sense, refers to:"}', '[{"id": "a", "text": {"en": "Only physical objects found at a crime scene"}}, {"id": "b", "text": {"en": "Encrypted files exclusively"}}, {"id": "c", "text": {"en": "A type of backup"}}, {"id": "d", "text": {"en": "Any trace left behind by activity on a system"}}]', 'd', null, 11),
  ('unit_exam', null, 'c02cf568-c225-4c83-8c1e-f164b04a57a5', null, '{"en": "Why is \"deleted\" often misleading in digital forensics?"}', '[{"id": "a", "text": {"en": "Deleted files are always instantly and completely gone"}}, {"id": "b", "text": {"en": "Deleted actions often still leave traces (artifacts) behind"}}, {"id": "c", "text": {"en": "Deletion has no relevance to forensics"}}, {"id": "d", "text": {"en": "Files can never actually be deleted at all"}}]', 'b', null, 12),
  ('unit_exam', null, 'c02cf568-c225-4c83-8c1e-f164b04a57a5', null, '{"en": "Which best summarizes the overall approach to sound digital forensics?"}', '[{"id": "a", "text": {"en": "Act fast and worry about documentation later"}}, {"id": "b", "text": {"en": "Analyze the original evidence directly to save time"}}, {"id": "c", "text": {"en": "Preserve evidence first, document every step, and maintain an unbroken chain of custody"}}, {"id": "d", "text": {"en": "Only investigate if the incident becomes a legal matter"}}]', 'c', null, 13),
  ('unit_exam', null, 'b6f3fb34-4367-4884-bcf2-1df17c9077ab', null, '{"en": "A SOC is:"}', '[{"id": "a", "text": {"en": "The team responsible for continuously monitoring, detecting, and responding to security threats"}}, {"id": "b", "text": {"en": "A type of firewall"}}, {"id": "c", "text": {"en": "A single automated tool"}}, {"id": "d", "text": {"en": "A physical building only"}}]', 'a', null, 1),
  ('unit_exam', null, 'b6f3fb34-4367-4884-bcf2-1df17c9077ab', null, '{"en": "Tier 1 analysts primarily:"}', '[{"id": "a", "text": {"en": "Handle only the most complex, proactive threat hunting"}}, {"id": "b", "text": {"en": "Manage the company''s finances"}}, {"id": "c", "text": {"en": "Never interact with alerts at all"}}, {"id": "d", "text": {"en": "Triage incoming alerts and filter out false positives"}}]', 'd', null, 2),
  ('unit_exam', null, 'b6f3fb34-4367-4884-bcf2-1df17c9077ab', null, '{"en": "Tier 3 analysts (threat hunters) often:"}', '[{"id": "a", "text": {"en": "Only handle basic password resets"}}, {"id": "b", "text": {"en": "Proactively search for threats that haven''t triggered any alert at all"}}, {"id": "c", "text": {"en": "Ignore complex cases entirely"}}, {"id": "d", "text": {"en": "Work exclusively on marketing tasks"}}]', 'b', null, 3),
  ('unit_exam', null, 'b6f3fb34-4367-4884-bcf2-1df17c9077ab', null, '{"en": "Why does a SOC typically operate around the clock?"}', '[{"id": "a", "text": {"en": "It''s required for no real reason"}}, {"id": "b", "text": {"en": "Attackers only work business hours"}}, {"id": "c", "text": {"en": "Attackers don''t work business hours, and detection speed matters significantly"}}, {"id": "d", "text": {"en": "It has nothing to do with damage limitation"}}]', 'c', null, 4),
  ('unit_exam', null, 'b6f3fb34-4367-4884-bcf2-1df17c9077ab', null, '{"en": "A SIEM system primarily:"}', '[{"id": "a", "text": {"en": "Centralizes logs from across an environment and correlates them to surface what matters"}}, {"id": "b", "text": {"en": "Physically blocks network traffic"}}, {"id": "c", "text": {"en": "Only stores backups"}}, {"id": "d", "text": {"en": "Replaces the need for any human analyst entirely"}}]', 'a', null, 5),
  ('unit_exam', null, 'b6f3fb34-4367-4884-bcf2-1df17c9077ab', null, '{"en": "Correlation in a SIEM is valuable because:"}', '[{"id": "a", "text": {"en": "A single log entry always tells the complete story"}}, {"id": "b", "text": {"en": "It has no real practical use"}}, {"id": "c", "text": {"en": "Combining multiple related events reveals patterns no individual log entry shows alone"}}, {"id": "d", "text": {"en": "It only works for very small companies"}}]', 'c', null, 6),
  ('unit_exam', null, 'b6f3fb34-4367-4884-bcf2-1df17c9077ab', null, '{"en": "A common challenge with SIEM tools is:"}', '[{"id": "a", "text": {"en": "They never generate false positives"}}, {"id": "b", "text": {"en": "They require no configuration whatsoever"}}, {"id": "c", "text": {"en": "They only work once, with no ongoing tuning needed"}}, {"id": "d", "text": {"en": "Poorly tuned rules can flood analysts with false positives"}}]', 'd', null, 7),
  ('unit_exam', null, 'b6f3fb34-4367-4884-bcf2-1df17c9077ab', null, '{"en": "A SOC''s effectiveness depends heavily on:"}', '[{"id": "a", "text": {"en": "Having the largest number of analysts possible"}}, {"id": "b", "text": {"en": "How well its SIEM is configured, not just the tool''s existence"}}, {"id": "c", "text": {"en": "Ignoring alerts entirely"}}, {"id": "d", "text": {"en": "Ignoring log data"}}]', 'b', null, 8),
  ('unit_exam', null, 'b6f3fb34-4367-4884-bcf2-1df17c9077ab', null, '{"en": "Threat intelligence is:"}', '[{"id": "a", "text": {"en": "Gathering, analyzing, and applying knowledge about active threats and attacker techniques"}}, {"id": "b", "text": {"en": "Guessing randomly about future attacks"}}, {"id": "c", "text": {"en": "Only relevant to government agencies"}}, {"id": "d", "text": {"en": "A type of firewall"}}]', 'a', null, 9),
  ('unit_exam', null, 'b6f3fb34-4367-4884-bcf2-1df17c9077ab', null, '{"en": "MITRE ATT&CK is best described as:"}', '[{"id": "a", "text": {"en": "A single antivirus product"}}, {"id": "b", "text": {"en": "A type of encryption standard"}}, {"id": "c", "text": {"en": "A physical security device"}}, {"id": "d", "text": {"en": "A structured knowledge base of real-world attacker tactics and techniques"}}]', 'd', null, 10),
  ('unit_exam', null, 'b6f3fb34-4367-4884-bcf2-1df17c9077ab', null, '{"en": "Why is a shared, structured vocabulary like ATT&CK helpful for defenders?"}', '[{"id": "a", "text": {"en": "It has no practical benefit"}}, {"id": "b", "text": {"en": "It slows down investigations unnecessarily"}}, {"id": "c", "text": {"en": "It lets teams reference exact techniques and compare them against known threat groups"}}, {"id": "d", "text": {"en": "It only applies to one specific company"}}]', 'c', null, 11),
  ('unit_exam', null, 'b6f3fb34-4367-4884-bcf2-1df17c9077ab', null, '{"en": "SOCs can use ATT&CK to:"}', '[{"id": "a", "text": {"en": "Ignore detection gaps entirely"}}, {"id": "b", "text": {"en": "Map detection coverage and identify blind spots in what techniques would go undetected"}}, {"id": "c", "text": {"en": "Randomly select which alerts to investigate"}}, {"id": "d", "text": {"en": "Replace the need for a SIEM entirely"}}]', 'b', null, 12),
  ('unit_exam', null, 'b6f3fb34-4367-4884-bcf2-1df17c9077ab', null, '{"en": "What ties together an effective SOC, a well-tuned SIEM, and threat intelligence frameworks like ATT&CK?"}', '[{"id": "a", "text": {"en": "They work together to turn raw data into prioritized, actionable defense"}}, {"id": "b", "text": {"en": "They have nothing to do with each other"}}, {"id": "c", "text": {"en": "Only one of them is ever needed"}}, {"id": "d", "text": {"en": "They replace the need for incident response entirely"}}]', 'a', null, 13),
  ('unit_exam', null, '7a916769-7e42-48ca-bf12-e7035b23238a', null, '{"en": "A security policy is:"}', '[{"id": "a", "text": {"en": "A type of firewall"}}, {"id": "b", "text": {"en": "A formal document defining an organization''s security rules and expectations"}}, {"id": "c", "text": {"en": "Only relevant to IT staff"}}, {"id": "d", "text": {"en": "An optional suggestion with no real weight"}}]', 'b', null, 1),
  ('unit_exam', null, '7a916769-7e42-48ca-bf12-e7035b23238a', null, '{"en": "An Acceptable Use Policy defines:"}', '[{"id": "a", "text": {"en": "Password complexity rules only"}}, {"id": "b", "text": {"en": "Risk ratings for vulnerabilities"}}, {"id": "c", "text": {"en": "Encryption standards only"}}, {"id": "d", "text": {"en": "What employees can and can''t do with company systems and data"}}]', 'd', null, 2),
  ('unit_exam', null, '7a916769-7e42-48ca-bf12-e7035b23238a', null, '{"en": "Why does a written policy matter more than assuming \"everyone knows the right thing\"?"}', '[{"id": "a", "text": {"en": "It doesn''t actually matter"}}, {"id": "b", "text": {"en": "Written policies are always ignored anyway"}}, {"id": "c", "text": {"en": "It removes ambiguity, especially as an organization grows"}}, {"id": "d", "text": {"en": "It only matters for very small teams"}}]', 'c', null, 3),
  ('unit_exam', null, '7a916769-7e42-48ca-bf12-e7035b23238a', null, '{"en": "A policy that exists only on paper, never enforced or trained on:"}', '[{"id": "a", "text": {"en": "Does almost nothing in practice"}}, {"id": "b", "text": {"en": "Is just as effective as an enforced one"}}, {"id": "c", "text": {"en": "Is illegal"}}, {"id": "d", "text": {"en": "Replaces the need for technical controls"}}]', 'a', null, 4),
  ('unit_exam', null, '7a916769-7e42-48ca-bf12-e7035b23238a', null, '{"en": "Risk is typically thought of as:"}', '[{"id": "a", "text": {"en": "Impact alone"}}, {"id": "b", "text": {"en": "Likelihood multiplied by impact"}}, {"id": "c", "text": {"en": "A random guess"}}, {"id": "d", "text": {"en": "Likelihood alone"}}]', 'b', null, 5),
  ('unit_exam', null, '7a916769-7e42-48ca-bf12-e7035b23238a', null, '{"en": "The first step in a typical risk assessment is:"}', '[{"id": "a", "text": {"en": "Identifying assets that need protecting"}}, {"id": "b", "text": {"en": "Deciding on treatment"}}, {"id": "c", "text": {"en": "Calculating final risk scores"}}, {"id": "d", "text": {"en": "Buying insurance"}}]', 'a', null, 6),
  ('unit_exam', null, '7a916769-7e42-48ca-bf12-e7035b23238a', null, '{"en": "\"Accepting\" a risk means:"}', '[{"id": "a", "text": {"en": "Ignoring all risks entirely without any decision"}}, {"id": "b", "text": {"en": "Automatically fixing every risk regardless of cost"}}, {"id": "c", "text": {"en": "Transferring the risk to an insurance company"}}, {"id": "d", "text": {"en": "Formally acknowledging a risk without necessarily fixing it, often because the cost outweighs the benefit"}}]', 'd', null, 7),
  ('unit_exam', null, '7a916769-7e42-48ca-bf12-e7035b23238a', null, '{"en": "The overall goal of risk assessment is to:"}', '[{"id": "a", "text": {"en": "Eliminate all risk completely, which is achievable with enough budget"}}, {"id": "b", "text": {"en": "Randomly select which vulnerabilities to fix"}}, {"id": "c", "text": {"en": "Make informed, deliberate decisions about which risks are worth addressing"}}, {"id": "d", "text": {"en": "Ignore likelihood and focus only on impact"}}]', 'c', null, 8),
  ('unit_exam', null, '7a916769-7e42-48ca-bf12-e7035b23238a', null, '{"en": "ISO 27001 is:"}', '[{"id": "a", "text": {"en": "A U.S. government law"}}, {"id": "b", "text": {"en": "An international standard for building and maintaining an Information Security Management System"}}, {"id": "c", "text": {"en": "A type of firewall"}}, {"id": "d", "text": {"en": "A single antivirus product"}}]', 'b', null, 9),
  ('unit_exam', null, '7a916769-7e42-48ca-bf12-e7035b23238a', null, '{"en": "The NIST Cybersecurity Framework organizes practice around five functions, including:"}', '[{"id": "a", "text": {"en": "Only \"Protect\" and nothing else"}}, {"id": "b", "text": {"en": "Marketing, Sales, and Support"}}, {"id": "c", "text": {"en": "Encryption, Firewalls, and VPNs exclusively"}}, {"id": "d", "text": {"en": "Identify, Protect, Detect, Respond, and Recover"}}]', 'd', null, 10),
  ('unit_exam', null, '7a916769-7e42-48ca-bf12-e7035b23238a', null, '{"en": "GDPR is:"}', '[{"id": "a", "text": {"en": "A European Union regulation with legal force and financial penalties for violations"}}, {"id": "b", "text": {"en": "An optional guideline with no legal weight"}}, {"id": "c", "text": {"en": "A certification for individual security professionals"}}, {"id": "d", "text": {"en": "A framework specific to the United States only"}}]', 'a', null, 11),
  ('unit_exam', null, '7a916769-7e42-48ca-bf12-e7035b23238a', null, '{"en": "Understanding major frameworks and regulations helps explain:"}', '[{"id": "a", "text": {"en": "Nothing relevant to everyday security work"}}, {"id": "b", "text": {"en": "Only how to pass an exam"}}, {"id": "c", "text": {"en": "Why certain security decisions get made the way they do in real organizations"}}, {"id": "d", "text": {"en": "How to write malware"}}]', 'c', null, 12),
  ('unit_exam', null, '7a916769-7e42-48ca-bf12-e7035b23238a', null, '{"en": "Policies, risk assessment, and frameworks like ISO 27001 or NIST all serve the same underlying purpose of:"}', '[{"id": "a", "text": {"en": "Replacing the need for any technical security controls"}}, {"id": "b", "text": {"en": "Turning security from ad hoc guesswork into a structured, accountable, and prioritized practice"}}, {"id": "c", "text": {"en": "Only satisfying legal requirements with no practical value"}}, {"id": "d", "text": {"en": "Slowing down every organization unnecessarily"}}]', 'b', null, 13),
  ('unit_exam', null, 'e601e536-aa07-4ea6-ac3a-75b4f25820ec', null, '{"en": "The core principle of Zero Trust is:"}', '[{"id": "a", "text": {"en": "Never trusting any user, device, or system by default, regardless of location"}}, {"id": "b", "text": {"en": "Trusting all internal network traffic by default"}}, {"id": "c", "text": {"en": "Building one extremely strong perimeter firewall"}}, {"id": "d", "text": {"en": "Eliminating the need for authentication"}}]', 'a', null, 1),
  ('unit_exam', null, 'e601e536-aa07-4ea6-ac3a-75b4f25820ec', null, '{"en": "The traditional \"castle and moat\" security model assumed:"}', '[{"id": "a", "text": {"en": "Every device must be verified constantly"}}, {"id": "b", "text": {"en": "No trust should ever be granted anywhere"}}, {"id": "c", "text": {"en": "Once inside the network perimeter, users and devices are generally trusted"}}, {"id": "d", "text": {"en": "The internet doesn''t exist"}}]', 'c', null, 2),
  ('unit_exam', null, 'e601e536-aa07-4ea6-ac3a-75b4f25820ec', null, '{"en": "Why did the shift toward Zero Trust happen?"}', '[{"id": "a", "text": {"en": "Firewalls became illegal"}}, {"id": "b", "text": {"en": "Remote work, cloud services, and mobile devices erased the traditional network perimeter"}}, {"id": "c", "text": {"en": "Passwords were banned"}}, {"id": "d", "text": {"en": "It has no real cause"}}]', 'b', null, 3),
  ('unit_exam', null, 'e601e536-aa07-4ea6-ac3a-75b4f25820ec', null, '{"en": "\"Assume breach\" as a Zero Trust tenet means:"}', '[{"id": "a", "text": {"en": "Assuming no breach will ever happen"}}, {"id": "b", "text": {"en": "Ignoring security entirely"}}, {"id": "c", "text": {"en": "Only protecting the network''s outer edge"}}, {"id": "d", "text": {"en": "Designing systems as if an attacker is already inside, minimizing what any single point can reach"}}]', 'd', null, 4),
  ('unit_exam', null, 'e601e536-aa07-4ea6-ac3a-75b4f25820ec', null, '{"en": "Microsegmentation, compared to traditional network segmentation, is:"}', '[{"id": "a", "text": {"en": "Far more fine-grained, sometimes down to individual applications or workloads"}}, {"id": "b", "text": {"en": "Exactly the same thing with a different name"}}, {"id": "c", "text": {"en": "Broader and less specific"}}, {"id": "d", "text": {"en": "Focused only on physical hardware"}}]', 'a', null, 5),
  ('unit_exam', null, 'e601e536-aa07-4ea6-ac3a-75b4f25820ec', null, '{"en": "Lateral movement refers to:"}', '[{"id": "a", "text": {"en": "Data traveling to a backup server"}}, {"id": "b", "text": {"en": "A type of encryption"}}, {"id": "c", "text": {"en": "Physical movement of hardware"}}, {"id": "d", "text": {"en": "An attacker moving from one compromised system to others within a network"}}]', 'd', null, 6),
  ('unit_exam', null, 'e601e536-aa07-4ea6-ac3a-75b4f25820ec', null, '{"en": "Microsegmentation is specifically designed to:"}', '[{"id": "a", "text": {"en": "Eliminate the need for any authentication"}}, {"id": "b", "text": {"en": "Increase network speed"}}, {"id": "c", "text": {"en": "Make lateral movement as difficult as possible for an attacker"}}, {"id": "d", "text": {"en": "Replace the need for firewalls entirely"}}]', 'c', null, 7),
  ('unit_exam', null, 'e601e536-aa07-4ea6-ac3a-75b4f25820ec', null, '{"en": "What makes microsegmentation practical at scale today?"}', '[{"id": "a", "text": {"en": "Nothing has changed; it''s always been easy"}}, {"id": "b", "text": {"en": "Software-defined networking and modern tools enforcing rules dynamically"}}, {"id": "c", "text": {"en": "Physical rewiring for every new rule"}}, {"id": "d", "text": {"en": "It''s actually impossible to implement"}}]', 'b', null, 8),
  ('unit_exam', null, 'e601e536-aa07-4ea6-ac3a-75b4f25820ec', null, '{"en": "Continuous verification means:"}', '[{"id": "a", "text": {"en": "Access decisions get reevaluated repeatedly throughout a session"}}, {"id": "b", "text": {"en": "Checking identity only once at login"}}, {"id": "c", "text": {"en": "Never checking any signals after initial login"}}, {"id": "d", "text": {"en": "Only checking passwords, nothing else"}}]', 'a', null, 9),
  ('unit_exam', null, 'e601e536-aa07-4ea6-ac3a-75b4f25820ec', null, '{"en": "\"Device health\" as a verification signal refers to:"}', '[{"id": "a", "text": {"en": "The physical temperature of a device"}}, {"id": "b", "text": {"en": "The device''s battery level only"}}, {"id": "c", "text": {"en": "Whether the device still meets security requirements, like being updated and not compromised"}}, {"id": "d", "text": {"en": "The device''s brand name"}}]', 'c', null, 10),
  ('unit_exam', null, 'e601e536-aa07-4ea6-ac3a-75b4f25820ec', null, '{"en": "Why does continuous verification matter more than a one-time login check?"}', '[{"id": "a", "text": {"en": "It doesn''t actually matter more"}}, {"id": "b", "text": {"en": "Credentials are never stolen in practice"}}, {"id": "c", "text": {"en": "One-time checks are always sufficient"}}, {"id": "d", "text": {"en": "A one-time check can''t catch what happens after that initial moment, like a stolen session or mid-session compromise"}}]', 'd', null, 11),
  ('unit_exam', null, 'e601e536-aa07-4ea6-ac3a-75b4f25820ec', null, '{"en": "The bigger shift continuous verification represents is:"}', '[{"id": "a", "text": {"en": "Removing all verification entirely"}}, {"id": "b", "text": {"en": "Moving from a single identity check to continuously asking whether the ongoing session still makes sense"}}, {"id": "c", "text": {"en": "Only verifying users once a year"}}, {"id": "d", "text": {"en": "Trusting every session permanently after the first check"}}]', 'b', null, 12),
  ('unit_exam', null, 'e601e536-aa07-4ea6-ac3a-75b4f25820ec', null, '{"en": "Zero Trust builds most directly on which two concepts from earlier in this course?"}', '[{"id": "a", "text": {"en": "Least privilege and network segmentation, applied continuously rather than as one-time decisions"}}, {"id": "b", "text": {"en": "Encryption and digital signatures only"}}, {"id": "c", "text": {"en": "Career certifications and GRC frameworks"}}, {"id": "d", "text": {"en": "Wireless security standards exclusively"}}]', 'a', null, 13),
  ('unit_exam', null, '3e04dc34-3cb6-42f0-aaae-faeee57fe7b0', null, '{"en": "Containers, unlike traditional virtual machines, typically:"}', '[{"id": "a", "text": {"en": "Each run a completely separate operating system"}}, {"id": "b", "text": {"en": "Are always slower to start than VMs"}}, {"id": "c", "text": {"en": "Have no security considerations at all"}}, {"id": "d", "text": {"en": "Share the underlying operating system kernel with other containers"}}]', 'd', null, 1),
  ('unit_exam', null, '3e04dc34-3cb6-42f0-aaae-faeee57fe7b0', null, '{"en": "A container escape is:"}', '[{"id": "a", "text": {"en": "A normal, harmless container shutdown"}}, {"id": "b", "text": {"en": "A flaw that lets code break out of its container boundary, potentially reaching the host"}}, {"id": "c", "text": {"en": "A backup procedure"}}, {"id": "d", "text": {"en": "A type of encryption"}}]', 'b', null, 2),
  ('unit_exam', null, '3e04dc34-3cb6-42f0-aaae-faeee57fe7b0', null, '{"en": "A vulnerable base image problem occurs when:"}', '[{"id": "a", "text": {"en": "A container is built on top of an outdated or already-compromised base image, inheriting its flaws"}}, {"id": "b", "text": {"en": "A container has too little functionality"}}, {"id": "c", "text": {"en": "A container runs too fast"}}, {"id": "d", "text": {"en": "A container uses too much memory"}}]', 'a', null, 3),
  ('unit_exam', null, '3e04dc34-3cb6-42f0-aaae-faeee57fe7b0', null, '{"en": "Good container security practice includes:"}', '[{"id": "a", "text": {"en": "Storing secrets directly inside container images for convenience"}}, {"id": "b", "text": {"en": "Running every container as root by default"}}, {"id": "c", "text": {"en": "Scanning images for known vulnerabilities before deployment"}}, {"id": "d", "text": {"en": "Never updating base images"}}]', 'c', null, 4),
  ('unit_exam', null, '3e04dc34-3cb6-42f0-aaae-faeee57fe7b0', null, '{"en": "A CI/CD pipeline is:"}', '[{"id": "a", "text": {"en": "A type of firewall"}}, {"id": "b", "text": {"en": "A physical network cable"}}, {"id": "c", "text": {"en": "A password policy"}}, {"id": "d", "text": {"en": "An automated process that builds, tests, and deploys code, often with minimal human involvement"}}]', 'd', null, 5),
  ('unit_exam', null, '3e04dc34-3cb6-42f0-aaae-faeee57fe7b0', null, '{"en": "Why has the CI/CD pipeline become a serious attack target?"}', '[{"id": "a", "text": {"en": "It has no real value to attackers"}}, {"id": "b", "text": {"en": "It''s always completely isolated from the internet"}}, {"id": "c", "text": {"en": "Compromising it can let an attacker inject malicious code that ships to production automatically"}}, {"id": "d", "text": {"en": "It only affects test environments, never production"}}]', 'c', null, 6),
  ('unit_exam', null, '3e04dc34-3cb6-42f0-aaae-faeee57fe7b0', null, '{"en": "Dependency poisoning refers to:"}', '[{"id": "a", "text": {"en": "A hardware failure"}}, {"id": "b", "text": {"en": "Injecting malicious code into a third-party package that gets automatically pulled into a build"}}, {"id": "c", "text": {"en": "A password reset procedure"}}, {"id": "d", "text": {"en": "A type of firewall rule"}}]', 'b', null, 7),
  ('unit_exam', null, '3e04dc34-3cb6-42f0-aaae-faeee57fe7b0', null, '{"en": "Secure CI/CD practice includes:"}', '[{"id": "a", "text": {"en": "Requiring code review and approval gates before changes reach the pipeline"}}, {"id": "b", "text": {"en": "Giving every developer unrestricted pipeline access"}}, {"id": "c", "text": {"en": "Never scanning dependencies for vulnerabilities"}}, {"id": "d", "text": {"en": "Storing pipeline credentials with no rotation or monitoring"}}]', 'a', null, 8),
  ('unit_exam', null, '3e04dc34-3cb6-42f0-aaae-faeee57fe7b0', null, '{"en": "Kubernetes primarily helps with:"}', '[{"id": "a", "text": {"en": "Writing application code"}}, {"id": "b", "text": {"en": "Designing user interfaces"}}, {"id": "c", "text": {"en": "Physical server manufacturing"}}, {"id": "d", "text": {"en": "Automatically deploying, scaling, and managing containers across a cluster of machines"}}]', 'd', null, 9),
  ('unit_exam', null, '3e04dc34-3cb6-42f0-aaae-faeee57fe7b0', null, '{"en": "Compromising the Kubernetes control plane can potentially give an attacker:"}', '[{"id": "a", "text": {"en": "Control over the entire cluster and everything running on it"}}, {"id": "b", "text": {"en": "Access to nothing significant"}}, {"id": "c", "text": {"en": "Only cosmetic changes to a dashboard"}}, {"id": "d", "text": {"en": "Access to a single, isolated container only"}}]', 'a', null, 10),
  ('unit_exam', null, '3e04dc34-3cb6-42f0-aaae-faeee57fe7b0', null, '{"en": "One of the most common, dangerous real-world Kubernetes misconfigurations is:"}', '[{"id": "a", "text": {"en": "Using too much RBAC"}}, {"id": "b", "text": {"en": "Having too many namespaces"}}, {"id": "c", "text": {"en": "The API server exposed to the internet without proper authentication"}}, {"id": "d", "text": {"en": "Updating the cluster too frequently"}}]', 'c', null, 11),
  ('unit_exam', null, '3e04dc34-3cb6-42f0-aaae-faeee57fe7b0', null, '{"en": "Kubernetes network policies are used to:"}', '[{"id": "a", "text": {"en": "Increase overall cluster speed only"}}, {"id": "b", "text": {"en": "Control which pods can actually communicate with each other, similar to microsegmentation"}}, {"id": "c", "text": {"en": "Automatically write application code"}}, {"id": "d", "text": {"en": "Replace the need for RBAC entirely"}}]', 'b', null, 12),
  ('unit_exam', null, '3e04dc34-3cb6-42f0-aaae-faeee57fe7b0', null, '{"en": "Least privilege, secure defaults, and segmentation reappear across cloud security, application security, and Kubernetes alike. This pattern shows that:"}', '[{"id": "a", "text": {"en": "These are unrelated, coincidental ideas"}}, {"id": "b", "text": {"en": "Only cloud security matters in practice"}}, {"id": "c", "text": {"en": "Kubernetes has nothing to do with any other unit in this course"}}, {"id": "d", "text": {"en": "Core security principles apply repeatedly across different layers of modern infrastructure"}}]', 'd', null, 13),
  ('unit_exam', null, '4155005a-28fb-4916-98ed-9703604bbd84', null, '{"en": "Traditional signature-based antivirus has an obvious blind spot:"}', '[{"id": "a", "text": {"en": "It works perfectly against everything"}}, {"id": "b", "text": {"en": "It requires no updates ever"}}, {"id": "c", "text": {"en": "It''s too fast to be useful"}}, {"id": "d", "text": {"en": "It can only catch threats it already recognizes from its signature database"}}]', 'd', null, 1),
  ('unit_exam', null, '4155005a-28fb-4916-98ed-9703604bbd84', null, '{"en": "Behavioral analysis in endpoint protection works by:"}', '[{"id": "a", "text": {"en": "Watching for suspicious patterns of behavior, like rapid mass file encryption"}}, {"id": "b", "text": {"en": "Only checking file names"}}, {"id": "c", "text": {"en": "Ignoring all running programs"}}, {"id": "d", "text": {"en": "Deleting every file automatically"}}]', 'a', null, 2),
  ('unit_exam', null, '4155005a-28fb-4916-98ed-9703604bbd84', null, '{"en": "Polymorphism, in the context of malware, refers to:"}', '[{"id": "a", "text": {"en": "A type of firewall"}}, {"id": "b", "text": {"en": "A backup strategy"}}, {"id": "c", "text": {"en": "Malicious code changing its own signature while keeping its harmful behavior intact"}}, {"id": "d", "text": {"en": "A password policy"}}]', 'c', null, 3),
  ('unit_exam', null, '4155005a-28fb-4916-98ed-9703604bbd84', null, '{"en": "Why has endpoint protection kept evolving beyond simple antivirus?"}', '[{"id": "a", "text": {"en": "It hasn''t actually changed at all"}}, {"id": "b", "text": {"en": "Attackers actively modify malware to dodge signature detection, requiring behavior-based approaches"}}, {"id": "c", "text": {"en": "Antivirus was always sufficient"}}, {"id": "d", "text": {"en": "Endpoints are no longer targeted by attackers"}}]', 'b', null, 4),
  ('unit_exam', null, '4155005a-28fb-4916-98ed-9703604bbd84', null, '{"en": "EDR stands for:"}', '[{"id": "a", "text": {"en": "Extended Data Retrieval"}}, {"id": "b", "text": {"en": "Encrypted Data Router"}}, {"id": "c", "text": {"en": "External Device Restriction"}}, {"id": "d", "text": {"en": "Endpoint Detection and Response"}}]', 'd', null, 5),
  ('unit_exam', null, '4155005a-28fb-4916-98ed-9703604bbd84', null, '{"en": "EDR tools continuously record:"}', '[{"id": "a", "text": {"en": "Only the device''s battery status"}}, {"id": "b", "text": {"en": "Detailed activity like process launches, file changes, and network connections on each endpoint"}}, {"id": "c", "text": {"en": "Nothing useful for investigation"}}, {"id": "d", "text": {"en": "Only user login times, and nothing else"}}]', 'b', null, 6),
  ('unit_exam', null, '4155005a-28fb-4916-98ed-9703604bbd84', null, '{"en": "What does EDR add beyond basic endpoint protection?"}', '[{"id": "a", "text": {"en": "Active response capability, like isolating a compromised endpoint automatically"}}, {"id": "b", "text": {"en": "Nothing meaningfully different"}}, {"id": "c", "text": {"en": "Only a nicer-looking dashboard"}}, {"id": "d", "text": {"en": "Slower detection times"}}]', 'a', null, 7),
  ('unit_exam', null, '4155005a-28fb-4916-98ed-9703604bbd84', null, '{"en": "Why does \"detection AND response\" matter as a combined concept?"}', '[{"id": "a", "text": {"en": "Detection alone is always sufficient"}}, {"id": "b", "text": {"en": "Response without detection is more effective"}}, {"id": "c", "text": {"en": "Detecting a threat without the ability to act on it quickly still leaves the door open"}}, {"id": "d", "text": {"en": "Neither detection nor response actually matters"}}]', 'c', null, 8),
  ('unit_exam', null, '4155005a-28fb-4916-98ed-9703604bbd84', null, '{"en": "Endpoint hardening is primarily about:"}', '[{"id": "a", "text": {"en": "Making an endpoint run faster"}}, {"id": "b", "text": {"en": "Adding more installed software"}}, {"id": "c", "text": {"en": "Increasing the attack surface deliberately"}}, {"id": "d", "text": {"en": "Reducing the number of ways an endpoint can actually be attacked"}}]', 'd', null, 9),
  ('unit_exam', null, '4155005a-28fb-4916-98ed-9703604bbd84', null, '{"en": "Why should unnecessary software be removed from an endpoint?"}', '[{"id": "a", "text": {"en": "It has no relationship to security"}}, {"id": "b", "text": {"en": "It always improves performance"}}, {"id": "c", "text": {"en": "Every installed application is a potential vulnerability waiting to be discovered"}}, {"id": "d", "text": {"en": "It''s required by law"}}]', 'c', null, 10),
  ('unit_exam', null, '4155005a-28fb-4916-98ed-9703604bbd84', null, '{"en": "Application allowlisting works by:"}', '[{"id": "a", "text": {"en": "Blocking only known-bad software"}}, {"id": "b", "text": {"en": "Only permitting pre-approved applications to run, blocking everything else by default"}}, {"id": "c", "text": {"en": "Allowing absolutely any application to run"}}, {"id": "d", "text": {"en": "Deleting all applications automatically"}}]', 'b', null, 11),
  ('unit_exam', null, '4155005a-28fb-4916-98ed-9703604bbd84', null, '{"en": "Why does hardening matter alongside detection tools like EDR?"}', '[{"id": "a", "text": {"en": "Every risk reduced through hardening is one less thing EDR ever needs to catch"}}, {"id": "b", "text": {"en": "Hardening replaces the need for EDR entirely"}}, {"id": "c", "text": {"en": "They''re unrelated and don''t work together"}}, {"id": "d", "text": {"en": "EDR makes hardening completely unnecessary"}}]', 'a', null, 12),
  ('unit_exam', null, '4155005a-28fb-4916-98ed-9703604bbd84', null, '{"en": "Together, hardening and EDR reflect which broader security principle from this course?"}', '[{"id": "a", "text": {"en": "Relying on a single control is always sufficient"}}, {"id": "b", "text": {"en": "Detection matters more than prevention"}}, {"id": "c", "text": {"en": "Prevention matters more than detection"}}, {"id": "d", "text": {"en": "Defense in depth - combining prevention (hardening) with detection and response (EDR) as complementary layers"}}]', 'd', null, 13),
  ('unit_exam', null, '6afb1a2b-30b3-4128-a038-afc471d3309e', null, '{"en": "Business Continuity (BC) primarily focuses on:"}', '[{"id": "a", "text": {"en": "Restoring IT systems after a disruption"}}, {"id": "b", "text": {"en": "Preventing every possible disruption completely"}}, {"id": "c", "text": {"en": "Keeping critical business functions running during a disruption"}}, {"id": "d", "text": {"en": "Only IT-specific recovery tasks"}}]', 'c', null, 1),
  ('unit_exam', null, '6afb1a2b-30b3-4128-a038-afc471d3309e', null, '{"en": "Disaster Recovery (DR) primarily focuses on:"}', '[{"id": "a", "text": {"en": "Keeping staff physically comfortable"}}, {"id": "b", "text": {"en": "Restoring IT systems and data after a disruption"}}, {"id": "c", "text": {"en": "Marketing during a crisis"}}, {"id": "d", "text": {"en": "Ignoring the disruption entirely"}}]', 'b', null, 2),
  ('unit_exam', null, '6afb1a2b-30b3-4128-a038-afc471d3309e', null, '{"en": "A simple way to distinguish BC from DR is:"}', '[{"id": "a", "text": {"en": "BC asks how to keep functioning now, DR asks how to get systems fully back to normal"}}, {"id": "b", "text": {"en": "They''re actually identical concepts"}}, {"id": "c", "text": {"en": "BC only applies to natural disasters"}}, {"id": "d", "text": {"en": "DR only applies to cyberattacks"}}]', 'a', null, 3),
  ('unit_exam', null, '6afb1a2b-30b3-4128-a038-afc471d3309e', null, '{"en": "An organization with a strong DR plan but no BC plan might:"}', '[{"id": "a", "text": {"en": "Never experience any problems"}}, {"id": "b", "text": {"en": "Automatically have a strong BC plan too"}}, {"id": "c", "text": {"en": "Have no need for backups"}}, {"id": "d", "text": {"en": "Still grind to a halt for hours because no one planned how staff would keep working during the outage"}}]', 'd', null, 4),
  ('unit_exam', null, '6afb1a2b-30b3-4128-a038-afc471d3309e', null, '{"en": "Recovery Time Objective (RTO) measures:"}', '[{"id": "a", "text": {"en": "How much data can be lost"}}, {"id": "b", "text": {"en": "The cost of a backup solution"}}, {"id": "c", "text": {"en": "How long a system can realistically be down before impact becomes unacceptable"}}, {"id": "d", "text": {"en": "The number of employees affected"}}]', 'c', null, 5),
  ('unit_exam', null, '6afb1a2b-30b3-4128-a038-afc471d3309e', null, '{"en": "Recovery Point Objective (RPO) measures:"}', '[{"id": "a", "text": {"en": "How fast a system can be restarted"}}, {"id": "b", "text": {"en": "The physical location of backups"}}, {"id": "c", "text": {"en": "The number of servers involved"}}, {"id": "d", "text": {"en": "How much data, measured in time, the organization can afford to lose"}}]', 'd', null, 6),
  ('unit_exam', null, '6afb1a2b-30b3-4128-a038-afc471d3309e', null, '{"en": "Why do RTO and RPO matter practically?"}', '[{"id": "a", "text": {"en": "They only matter for very small companies"}}, {"id": "b", "text": {"en": "They directly determine the technical solution required and its cost"}}, {"id": "c", "text": {"en": "They''re purely theoretical numbers with no application"}}, {"id": "d", "text": {"en": "They have no real practical impact"}}]', 'b', null, 7),
  ('unit_exam', null, '6afb1a2b-30b3-4128-a038-afc471d3309e', null, '{"en": "A common mistake organizations make with RTO/RPO is:"}', '[{"id": "a", "text": {"en": "Treating every system as equally critical, wasting resources or under-protecting what matters most"}}, {"id": "b", "text": {"en": "Setting them too precisely"}}, {"id": "c", "text": {"en": "Never using them at all"}}, {"id": "d", "text": {"en": "Only applying them to marketing systems"}}]', 'a', null, 8),
  ('unit_exam', null, '6afb1a2b-30b3-4128-a038-afc471d3309e', null, '{"en": "A tabletop exercise involves:"}', '[{"id": "a", "text": {"en": "Fully failing over to backup systems in production"}}, {"id": "b", "text": {"en": "Ignoring the plan entirely"}}, {"id": "c", "text": {"en": "The team talking through a scenario step by step without touching actual systems"}}, {"id": "d", "text": {"en": "Only reading the plan silently alone"}}]', 'c', null, 9),
  ('unit_exam', null, '6afb1a2b-30b3-4128-a038-afc471d3309e', null, '{"en": "Which of these is the most realistic form of BC/DR testing?"}', '[{"id": "a", "text": {"en": "A full simulation, actually failing over and restoring from real backups"}}, {"id": "b", "text": {"en": "Never testing at all"}}, {"id": "c", "text": {"en": "Only reading the plan once"}}, {"id": "d", "text": {"en": "Guessing what might happen"}}]', 'a', null, 10),
  ('unit_exam', null, '6afb1a2b-30b3-4128-a038-afc471d3309e', null, '{"en": "Testing a BC/DR plan commonly reveals:"}', '[{"id": "a", "text": {"en": "That plans never have any flaws"}}, {"id": "b", "text": {"en": "Nothing useful ever"}}, {"id": "c", "text": {"en": "That testing is unnecessary"}}, {"id": "d", "text": {"en": "Backups that wouldn''t actually restore properly, or outdated contact information"}}]', 'd', null, 11),
  ('unit_exam', null, '6afb1a2b-30b3-4128-a038-afc471d3309e', null, '{"en": "Why does regular BC/DR testing matter so much?"}', '[{"id": "a", "text": {"en": "It has no real value"}}, {"id": "b", "text": {"en": "The worst moment to discover a plan doesn''t work is during an actual crisis"}}, {"id": "c", "text": {"en": "Plans never need updating once written"}}, {"id": "d", "text": {"en": "Testing replaces the need for a written plan entirely"}}]', 'b', null, 12),
  ('unit_exam', null, '6afb1a2b-30b3-4128-a038-afc471d3309e', null, '{"en": "BC/DR planning, at its core, is best understood as an organization-wide application of which concept from earlier in this course?"}', '[{"id": "a", "text": {"en": "Zero Trust exclusively"}}, {"id": "b", "text": {"en": "Digital signatures"}}, {"id": "c", "text": {"en": "The Recovery phase of the Incident Response lifecycle, scaled beyond a single system"}}, {"id": "d", "text": {"en": "Application security testing"}}]', 'c', null, 13),
  ('unit_exam', null, '42959e6b-1565-47d6-a374-650aec9c4183', null, '{"en": "Third-party risk refers to:"}', '[{"id": "a", "text": {"en": "Risk that only exists within your own organization"}}, {"id": "b", "text": {"en": "The security exposure introduced by every vendor, contractor, and service provider connected to your systems"}}, {"id": "c", "text": {"en": "A type of firewall"}}, {"id": "d", "text": {"en": "A risk that never actually matters in practice"}}]', 'b', null, 1),
  ('unit_exam', null, '42959e6b-1565-47d6-a374-650aec9c4183', null, '{"en": "Why do attackers often target third parties rather than a well-defended organization directly?"}', '[{"id": "a", "text": {"en": "Third parties are never actually connected to anything important"}}, {"id": "b", "text": {"en": "It''s illegal to attack the main organization"}}, {"id": "c", "text": {"en": "Third parties are always better defended"}}, {"id": "d", "text": {"en": "The weakest link in the chain is often easier to compromise"}}]', 'd', null, 2),
  ('unit_exam', null, '42959e6b-1565-47d6-a374-650aec9c4183', null, '{"en": "Software dependencies as a third-party risk category means:"}', '[{"id": "a", "text": {"en": "Your software has no external dependencies ever"}}, {"id": "b", "text": {"en": "Dependencies have nothing to do with security"}}, {"id": "c", "text": {"en": "Every third-party library or service your software relies on inherits that provider''s security posture"}}, {"id": "d", "text": {"en": "Only hardware counts as a dependency"}}]', 'c', null, 3),
  ('unit_exam', null, '42959e6b-1565-47d6-a374-650aec9c4183', null, '{"en": "The uncomfortable truth about supply chain security is that:"}', '[{"id": "a", "text": {"en": "You can''t fully control a vendor''s security the way you control your own"}}, {"id": "b", "text": {"en": "You always have full control over every vendor"}}, {"id": "c", "text": {"en": "Vendors never pose any real risk"}}, {"id": "d", "text": {"en": "It requires no ongoing process at all"}}]', 'a', null, 4),
  ('unit_exam', null, '42959e6b-1565-47d6-a374-650aec9c4183', null, '{"en": "A software supply chain attack typically involves:"}', '[{"id": "a", "text": {"en": "Attacking thousands of individual targets one at a time directly"}}, {"id": "b", "text": {"en": "Compromising a single trusted piece of software that many organizations then willingly install"}}, {"id": "c", "text": {"en": "Only physical theft of hardware"}}, {"id": "d", "text": {"en": "No trust relationship at all"}}]', 'b', null, 5),
  ('unit_exam', null, '42959e6b-1565-47d6-a374-650aec9c4183', null, '{"en": "Typosquatting applied to software packages means:"}', '[{"id": "a", "text": {"en": "Publishing a malicious package with a name deceptively similar to a popular one"}}, {"id": "b", "text": {"en": "Making genuine typing mistakes while coding"}}, {"id": "c", "text": {"en": "A type of firewall setting"}}, {"id": "d", "text": {"en": "A backup naming convention"}}]', 'a', null, 6),
  ('unit_exam', null, '42959e6b-1565-47d6-a374-650aec9c4183', null, '{"en": "Why are software supply chain attacks so devastating?"}', '[{"id": "a", "text": {"en": "They only ever affect one organization at a time"}}, {"id": "b", "text": {"en": "They''re always immediately obvious to victims"}}, {"id": "c", "text": {"en": "They have no real impact in practice"}}, {"id": "d", "text": {"en": "They exploit trust at scale, reaching many organizations through one compromised source"}}]', 'd', null, 7),
  ('unit_exam', null, '42959e6b-1565-47d6-a374-650aec9c4183', null, '{"en": "A recommended defense approach against supply chain attacks includes:"}', '[{"id": "a", "text": {"en": "Trusting every vendor completely with no further verification"}}, {"id": "b", "text": {"en": "Ignoring what software is actually running in your environment"}}, {"id": "c", "text": {"en": "Monitoring software behavior even after installation and maintaining a clear software inventory"}}, {"id": "d", "text": {"en": "Never updating any software ever"}}]', 'c', null, 8),
  ('unit_exam', null, '42959e6b-1565-47d6-a374-650aec9c4183', null, '{"en": "A Software Bill of Materials (SBOM) is:"}', '[{"id": "a", "text": {"en": "A financial invoice for software purchases"}}, {"id": "b", "text": {"en": "A detailed inventory of every component, library, and dependency that makes up an application"}}, {"id": "c", "text": {"en": "A type of firewall"}}, {"id": "d", "text": {"en": "A backup schedule"}}]', 'b', null, 9),
  ('unit_exam', null, '42959e6b-1565-47d6-a374-650aec9c4183', null, '{"en": "Why is an SBOM valuable when a new vulnerability is discovered in some dependency?"}', '[{"id": "a", "text": {"en": "It has no practical value"}}, {"id": "b", "text": {"en": "It automatically fixes every vulnerability"}}, {"id": "c", "text": {"en": "It replaces the need for patching entirely"}}, {"id": "d", "text": {"en": "It lets you quickly determine whether that vulnerable dependency is actually present in your software"}}]', 'd', null, 10),
  ('unit_exam', null, '42959e6b-1565-47d6-a374-650aec9c4183', null, '{"en": "Least privilege applied to vendors means:"}', '[{"id": "a", "text": {"en": "Giving a vendor only the access genuinely required for their specific role"}}, {"id": "b", "text": {"en": "Giving every vendor full access to everything"}}, {"id": "c", "text": {"en": "Removing all vendor access permanently"}}, {"id": "d", "text": {"en": "Ignoring what access vendors actually have"}}]', 'a', null, 11),
  ('unit_exam', null, '42959e6b-1565-47d6-a374-650aec9c4183', null, '{"en": "Why should supply chain security be treated as an ongoing discipline rather than a one-time audit?"}', '[{"id": "a", "text": {"en": "A vendor''s security posture is always permanently fixed once assessed"}}, {"id": "b", "text": {"en": "One-time audits are always sufficient"}}, {"id": "c", "text": {"en": "A vendor''s security posture can change over time, so continuous monitoring matters"}}, {"id": "d", "text": {"en": "Ongoing monitoring has no real value"}}]', 'c', null, 12),
  ('unit_exam', null, '42959e6b-1565-47d6-a374-650aec9c4183', null, '{"en": "SBOM, vendor risk assessment, least privilege, and continuous monitoring in supply chain security all illustrate that:"}', '[{"id": "a", "text": {"en": "These concepts are unique to supply chain security only"}}, {"id": "b", "text": {"en": "Core practices from earlier in this course apply outward to every third party connected to an organization"}}, {"id": "c", "text": {"en": "Vendors require no security consideration at all"}}, {"id": "d", "text": {"en": "Supply chain security has nothing to do with the rest of this course"}}]', 'b', null, 13),
  ('unit_exam', null, '22a1be2f-f9e1-48bc-901f-a90585d01820', null, '{"en": "Prompt injection is best understood as:"}', '[{"id": "a", "text": {"en": "A type of network firewall"}}, {"id": "b", "text": {"en": "A backup strategy for AI systems"}}, {"id": "c", "text": {"en": "A password policy specific to AI tools"}}, {"id": "d", "text": {"en": "The AI-era equivalent of injection attacks, where hidden instructions get embedded in content an AI processes"}}]', 'd', null, 1),
  ('unit_exam', null, '22a1be2f-f9e1-48bc-901f-a90585d01820', null, '{"en": "In a realistic prompt injection scenario, hidden instructions might be embedded in:"}', '[{"id": "a", "text": {"en": "Only in the AI''s original training data"}}, {"id": "b", "text": {"en": "A webpage or document the AI is asked to summarize"}}, {"id": "c", "text": {"en": "Nowhere; this scenario never actually happens"}}, {"id": "d", "text": {"en": "Only in encrypted files that can''t be read"}}]', 'b', null, 2),
  ('unit_exam', null, '22a1be2f-f9e1-48bc-901f-a90585d01820', null, '{"en": "Why is prompt injection a genuinely hard problem to solve?"}', '[{"id": "a", "text": {"en": "Language models process everything as text, and the boundary between instructions and untrusted content isn''t always structurally enforced"}}, {"id": "b", "text": {"en": "It isn''t actually a hard problem at all"}}, {"id": "c", "text": {"en": "AI systems never process any external text"}}, {"id": "d", "text": {"en": "It''s identical to a hardware failure"}}]', 'a', null, 3),
  ('unit_exam', null, '22a1be2f-f9e1-48bc-901f-a90585d01820', null, '{"en": "Jailbreaking, in the context of AI, refers to:"}', '[{"id": "a", "text": {"en": "A physical security bypass technique"}}, {"id": "b", "text": {"en": "A type of encryption"}}, {"id": "c", "text": {"en": "Crafting inputs specifically designed to bypass an AI system''s safety guidelines"}}, {"id": "d", "text": {"en": "A network segmentation technique"}}]', 'c', null, 4),
  ('unit_exam', null, '22a1be2f-f9e1-48bc-901f-a90585d01820', null, '{"en": "Data poisoning is:"}', '[{"id": "a", "text": {"en": "A physical attack on server hardware"}}, {"id": "b", "text": {"en": "A type of firewall rule"}}, {"id": "c", "text": {"en": "A backup corruption issue only"}}, {"id": "d", "text": {"en": "An attack where corrupted or misleading data is deliberately introduced to influence what a model learns"}}]', 'd', null, 5),
  ('unit_exam', null, '22a1be2f-f9e1-48bc-901f-a90585d01820', null, '{"en": "A backdoor attack on a machine learning model:"}', '[{"id": "a", "text": {"en": "Always makes the model obviously malfunction immediately"}}, {"id": "b", "text": {"en": "Has nothing to do with training data"}}, {"id": "c", "text": {"en": "Makes the model behave normally except when it encounters a specific attacker-planted trigger"}}, {"id": "d", "text": {"en": "Is identical to a network firewall bypass"}}]', 'c', null, 6),
  ('unit_exam', null, '22a1be2f-f9e1-48bc-901f-a90585d01820', null, '{"en": "Why are backdoor attacks especially hard to catch through normal testing?"}', '[{"id": "a", "text": {"en": "They''re always caught immediately by any test"}}, {"id": "b", "text": {"en": "The model looks fine unless you happen to test for that exact trigger"}}, {"id": "c", "text": {"en": "They don''t actually affect model behavior at all"}}, {"id": "d", "text": {"en": "Testing has no relevance to this issue"}}]', 'b', null, 7),
  ('unit_exam', null, '22a1be2f-f9e1-48bc-901f-a90585d01820', null, '{"en": "Model provenance refers to:"}', '[{"id": "a", "text": {"en": "Where a model came from and how it was trained"}}, {"id": "b", "text": {"en": "The model''s file size"}}, {"id": "c", "text": {"en": "The color scheme of a model''s interface"}}, {"id": "d", "text": {"en": "The model''s programming language"}}]', 'a', null, 8),
  ('unit_exam', null, '22a1be2f-f9e1-48bc-901f-a90585d01820', null, '{"en": "Anomaly detection using AI in cybersecurity works by:"}', '[{"id": "a", "text": {"en": "Randomly flagging activity with no learning involved"}}, {"id": "b", "text": {"en": "Only detecting physical hardware failures"}}, {"id": "c", "text": {"en": "Replacing the need for any human analyst entirely"}}, {"id": "d", "text": {"en": "Learning what \"normal\" activity looks like and flagging genuine deviations from it"}}]', 'd', null, 9),
  ('unit_exam', null, '22a1be2f-f9e1-48bc-901f-a90585d01820', null, '{"en": "A genuine limitation of AI-based security tools is that:"}', '[{"id": "a", "text": {"en": "They make probabilistic judgments and can produce false positives and false negatives"}}, {"id": "b", "text": {"en": "They are always completely accurate with zero errors"}}, {"id": "c", "text": {"en": "They have no limitations whatsoever"}}, {"id": "d", "text": {"en": "They never require any human oversight"}}]', 'a', null, 10),
  ('unit_exam', null, '22a1be2f-f9e1-48bc-901f-a90585d01820', null, '{"en": "Adversarial awareness, in this context, refers to:"}', '[{"id": "a", "text": {"en": "AI systems being aware of nothing at all"}}, {"id": "b", "text": {"en": "A type of encryption"}}, {"id": "c", "text": {"en": "Sophisticated attackers studying how AI-based defenses work in order to evade them"}}, {"id": "d", "text": {"en": "A backup strategy"}}]', 'c', null, 11),
  ('unit_exam', null, '22a1be2f-f9e1-48bc-901f-a90585d01820', null, '{"en": "The course''s closing thought emphasizes that:"}', '[{"id": "a", "text": {"en": "AI replaces every fundamental concept learned earlier in this course"}}, {"id": "b", "text": {"en": "Understanding how something works, how it can be abused, and how to respond in layers is the pattern that stays useful regardless of the technology"}}, {"id": "c", "text": {"en": "Technology change makes earlier fundamentals irrelevant"}}, {"id": "d", "text": {"en": "Only the newest technology matters going forward"}}]', 'b', null, 12),
  ('unit_exam', null, '22a1be2f-f9e1-48bc-901f-a90585d01820', null, '{"en": "AI security, spanning both attack surface and defensive use, ultimately confirms which idea running through this entire course?"}', '[{"id": "a", "text": {"en": "AI is fundamentally different from every other technology covered"}}, {"id": "b", "text": {"en": "Only the newest tools matter, and older principles are now obsolete"}}, {"id": "c", "text": {"en": "Security tools alone are sufficient without underlying principles"}}, {"id": "d", "text": {"en": "The same core principles - understanding mechanisms, anticipating abuse, and layering defenses - apply to any new technology, AI included"}}]', 'd', null, 13),
  ('unit_exam', null, '7a1de415-3a43-490d-b119-0c29b6793141', null, '{"en": "A SOC Analyst primarily focuses on:"}', '[{"id": "a", "text": {"en": "Designing overall security architecture"}}, {"id": "b", "text": {"en": "Authorized attacks to find vulnerabilities"}}, {"id": "c", "text": {"en": "Legal compliance frameworks exclusively"}}, {"id": "d", "text": {"en": "Frontline monitoring, investigating alerts, and escalating incidents"}}]', 'd', null, 1),
  ('unit_exam', null, '7a1de415-3a43-490d-b119-0c29b6793141', null, '{"en": "A Penetration Tester''s work involves:"}', '[{"id": "a", "text": {"en": "Only writing policy documents"}}, {"id": "b", "text": {"en": "Performing authorized attacks to find vulnerabilities before real attackers do"}}, {"id": "c", "text": {"en": "Legal compliance work only"}}, {"id": "d", "text": {"en": "Passive monitoring exclusively"}}]', 'b', null, 2),
  ('unit_exam', null, '7a1de415-3a43-490d-b119-0c29b6793141', null, '{"en": "A GRC Analyst primarily works on:"}', '[{"id": "a", "text": {"en": "Ensuring an organization meets relevant frameworks and regulations"}}, {"id": "b", "text": {"en": "Writing exploit code"}}, {"id": "c", "text": {"en": "Building firewalls exclusively"}}, {"id": "d", "text": {"en": "Digital forensics investigations"}}]', 'a', null, 3),
  ('unit_exam', null, '7a1de415-3a43-490d-b119-0c29b6793141', null, '{"en": "Why does the variety of cybersecurity roles matter?"}', '[{"id": "a", "text": {"en": "It doesn''t matter; every role is identical"}}, {"id": "b", "text": {"en": "Only one role is actually legitimate"}}, {"id": "c", "text": {"en": "Different roles suit genuinely different skills and interests"}}, {"id": "d", "text": {"en": "All roles require the exact same daily tasks"}}]', 'c', null, 4),
  ('unit_exam', null, '7a1de415-3a43-490d-b119-0c29b6793141', null, '{"en": "CompTIA Security+ is best described as:"}', '[{"id": "a", "text": {"en": "A senior-level, highly specialized certification"}}, {"id": "b", "text": {"en": "Exclusively for penetration testers"}}, {"id": "c", "text": {"en": "A physical security credential"}}, {"id": "d", "text": {"en": "An entry-level certification validating foundational knowledge"}}]', 'd', null, 5),
  ('unit_exam', null, '7a1de415-3a43-490d-b119-0c29b6793141', null, '{"en": "OSCP is widely respected because:"}', '[{"id": "a", "text": {"en": "It''s entirely multiple-choice with no practical component"}}, {"id": "b", "text": {"en": "It requires no preparation at all"}}, {"id": "c", "text": {"en": "It requires actually compromising systems in a hands-on, timed practical exam"}}, {"id": "d", "text": {"en": "It''s the easiest certification to obtain"}}]', 'c', null, 6),
  ('unit_exam', null, '7a1de415-3a43-490d-b119-0c29b6793141', null, '{"en": "CISSP typically requires:"}', '[{"id": "a", "text": {"en": "No prior experience whatsoever"}}, {"id": "b", "text": {"en": "Several years of relevant work experience before eligibility"}}, {"id": "c", "text": {"en": "Only a high school diploma"}}, {"id": "d", "text": {"en": "Passing a purely practical hacking exam"}}]', 'b', null, 7),
  ('unit_exam', null, '7a1de415-3a43-490d-b119-0c29b6793141', null, '{"en": "The honest truth about certifications, according to this lesson, is that:"}', '[{"id": "a", "text": {"en": "They open doors but don''t replace genuine, hands-on skill"}}, {"id": "b", "text": {"en": "They guarantee a job regardless of skill"}}, {"id": "c", "text": {"en": "They''re completely useless"}}, {"id": "d", "text": {"en": "Only one certification is ever worth pursuing"}}]', 'a', null, 8),
  ('unit_exam', null, '7a1de415-3a43-490d-b119-0c29b6793141', null, '{"en": "A commonly recommended way to build practical skill is to:"}', '[{"id": "a", "text": {"en": "Avoid any hands-on practice entirely"}}, {"id": "b", "text": {"en": "Only read certification study guides"}}, {"id": "c", "text": {"en": "Wait until landing a job to learn anything practical"}}, {"id": "d", "text": {"en": "Practice on legal platforms designed for this, like TryHackMe or HackTheBox"}}]', 'd', null, 9),
  ('unit_exam', null, '7a1de415-3a43-490d-b119-0c29b6793141', null, '{"en": "Why does early breadth (rather than immediate specialization) tend to help?"}', '[{"id": "a", "text": {"en": "You don''t yet know which area genuinely excites you until you''ve been exposed to several"}}, {"id": "b", "text": {"en": "It never actually helps"}}, {"id": "c", "text": {"en": "Specialization should always happen immediately"}}, {"id": "d", "text": {"en": "Breadth has no relationship to career direction"}}]', 'a', null, 10),
  ('unit_exam', null, '7a1de415-3a43-490d-b119-0c29b6793141', null, '{"en": "Networking (professional connections) matters in this field because:"}', '[{"id": "a", "text": {"en": "It has no real impact on opportunities"}}, {"id": "b", "text": {"en": "It''s only useful for non-technical roles"}}, {"id": "c", "text": {"en": "Many opportunities come through people who already know your work"}}, {"id": "d", "text": {"en": "It replaces the need for any technical skill"}}]', 'c', null, 11),
  ('unit_exam', null, '7a1de415-3a43-490d-b119-0c29b6793141', null, '{"en": "According to this unit, what actually carries a career forward long-term?"}', '[{"id": "a", "text": {"en": "Memorizing every current fact permanently"}}, {"id": "b", "text": {"en": "Understanding why a threat works and how defenses actually address it, not just memorizing specific facts"}}, {"id": "c", "text": {"en": "Avoiding any new information after certification"}}, {"id": "d", "text": {"en": "Ignoring how the field changes over time"}}]', 'b', null, 12),
  ('unit_exam', null, '7a1de415-3a43-490d-b119-0c29b6793141', null, '{"en": "Across all sixteen units of this course, the recurring theme has been:"}', '[{"id": "a", "text": {"en": "Memorizing isolated facts with no connection between them"}}, {"id": "b", "text": {"en": "Only one single tool solves every security problem"}}, {"id": "c", "text": {"en": "Security is entirely someone else''s responsibility"}}, {"id": "d", "text": {"en": "Understanding why attacks and defenses work, since that understanding transfers across every role, tool, and technology that comes next"}}]', 'd', null, 13);
